(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0009.js"] = [{"id":"poem-3c6a611450ed8237043b5edb","title":"送孔征士","author":"皇甫曾","dynasty":"唐","verses":["谷口山多处，君归不可寻。","家贫青史在，身老白云深。","扫雪开松径，疏泉过竹林。","余生负丘壑，相送亦何心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5bb0cf37-0685-4b52-b9b5-45e959d05e12","tags":[]},{"id":"poem-3c6baa3497733d6b17273c7b","title":"寻陈处士山堂","author":"刘得仁","dynasty":"唐","verses":["步溪凡几转，始得见幽踪。","路隐千根树，门开万仞峰。","片云生石窦，浅水卧枯松。","穷谷风光冷，深山翠碧浓。","鹤看空里过，仙向坐中逢。","底露秋潭水，声微暮观钟。","他年来此定，异日愿相容。","且喜今归去，人间事更慵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b022a966-3974-4005-83f9-3e0fbad78f47","tags":[]},{"id":"poem-3c70db3a760d2e7a76b748b1","title":"老人星","author":"赵蕃","dynasty":"唐","verses":["大史占南极，秋分见寿星。","增辉延宝历，发曜起祥经。","灼烁依狼地，昭彰近帝庭。","高悬方杳杳，孤白乍荧荧。","应见光新吐，休征德自形。","既能符圣柞，从此表遐龄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-820e1560-e3c9-4601-a27e-eaa404a6f878","tags":[]},{"id":"poem-3c894568432ab4e665389ffc","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十","author":"易静","dynasty":"唐","verses":["闻贼去，大吉是其元。","若在干（辛本、川本、京本作「前」）时应末去，若临干（辛本、川本、京本作「贼」）后是虚传，勿听此狂言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1a39bd9e-b4f6-40a5-9659-c5a132ce3b4e","tags":[]},{"id":"poem-3c899842353eb08bbd06c954","title":"九歌·东君","author":"屈原","dynasty":"先秦","verses":["暾将出兮东方，照吾槛兮扶桑。","抚余马兮安驱，夜皎皎兮既明。","驾龙辀兮乘雷，载云旗兮委蛇。","长太息兮将上，心低徊兮顾怀。","羌声色兮娱人，观者儋兮忘归。","縆瑟兮交鼓，萧钟兮瑶簴。","鸣篪兮吹竽，思灵保兮贤姱。","翾飞兮翠曾，展诗兮会舞。","应律兮合节，灵之来兮敝日。","青云衣兮白霓裳，举长矢兮射天狼。","操余弧兮反沦降，援北斗兮酌桂浆。","撰余辔兮高驰翔，杳冥冥兮以东行。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-7","tags":[]},{"id":"poem-3c97b6d6744e7ae854f756bc","title":"南海旅次","author":"曹松","dynasty":"唐","verses":["忆归休上越王台，归思临高不易裁。","为客正当无鴈处，故园谁道有书来。","城头早角吹霜尽，郭里残潮荡月回。","心似百花开未得，年年争发被春催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c6b6a68f-07a9-4a33-a026-712d302704ee","tags":[]},{"id":"poem-3c9de6203416be5d4a0b62c2","title":"文王","author":"佚名","dynasty":"先秦","verses":["文王在上，于昭于天。周虽旧邦，其命维新。有周不显，帝命不时。文王陟降，在帝左右。","亹亹文王，令闻不已。陈锡哉周，侯文王孙子。文王孙子，本支百世，凡周之士，不显亦世。","世之不显，厥犹翼翼。思皇多士，生此王国。王国克生，维周之桢；济济多士，文王以宁。","穆穆文王，于缉熙敬止。假哉天命。有商孙子。商之孙子，其丽不亿。上帝既命，侯于周服。","侯服于周，天命靡常。殷士肤敏。裸将于京。厥作裸将，常服黼冔。王之荩臣。无念尔祖。","无念尔祖，聿修厥德。永言配命，自求多福。殷之未丧师，克配上帝。宜鉴于殷，骏命不易！","命之不易，无遏尔躬。宣昭义问，有虞殷自天。上天之载，无声无臭。仪刑文王，万邦作孚。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-234","tags":[]},{"id":"poem-3ca9061fc79542dad8e80ef3","title":"达道场与城阴行者颂","author":"智闲","dynasty":"唐","verses":["理奥绝思量，根寻径路长。","因兹知隔濶，无那被封疆。","人生须特达，起坐觉馨香。","清净如来子，安然坐道场。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-98b03d81-40e0-4db4-9390-e85dbeaaa859","tags":[]},{"id":"poem-3ca91ed7ff98dbeb95c3b2b8","title":"哭亦周  其二","author":"赵文","dynasty":"宋","verses":["堂上华颠泣欲枯，哭声那解到黄垆。","千般欲解郄公意，难得嘉宾一箧书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6f8d056f-4587-4300-8308-6ef94530cc0d","tags":[]},{"id":"poem-3cac010d7d5b81e72cfa580d","title":"送丁少府往唐上","author":"李端","dynasty":"唐","verses":["因君灞陵别，故国一回看。","共食田文饭，先之梅福官。","江风转日暮，山月满潮寒。","不得同舟望，淹留岁月阑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-aba0b6ed-1b47-4c35-bd39-17a4a4a069b5","tags":[]},{"id":"poem-3cb07fe19eed8361d6221bad","title":"诣李侍郎","author":"王鲁复","dynasty":"唐","verses":["文字元无底，功夫转到难。","苦心三百首，暂请侍郎看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4ff4f244-0714-4046-8b5f-069cf67d1b5a","tags":[]},{"id":"poem-3cba5ed6223fd1d562c698c9","title":"新楼诗二十首","author":"李绅","dynasty":"唐","verses":["银地溪边遇衲师，笑将花宇指潜知。","定观玄度生前事，不道灵山别后期。","真相有无因色界，化城兴灭在莲基。","好令沧海龙宫子，长护金人旧浴池。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-08a50e12-2888-4249-9484-88f440012324","tags":[]},{"id":"poem-3cbc3fa57320acac2788b783","title":"新水令","author":"徐田臣《杀狗记》","dynasty":"元","verses":["奴家年少多聪慧，伴娘行宴乐游戏。","昼永拈针指。","(旦叫介)迎春！(贴)听帘前呼唤，不知有何言语？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1702","tags":[]},{"id":"poem-3cbddd509ba7ad02d1c7e025","title":"下池  其二","author":"释居简","dynasty":"宋","verses":["老子随行苜蓿盘，不曾无客自开单。","更将余粒投清浅，聊为游鱼小倚阑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f8a5a4ae-e4aa-4b7e-8e3d-1c31afab6f88","tags":[]},{"id":"poem-3cc167f7ec1ddf5b115d8d00","title":"引驾行·虹收残雨","author":"柳永","dynasty":"宋","verses":["虹收残雨。","蝉嘶败柳长堤暮。","背都门、动消黯，西风片帆轻举。","愁睹。","泛画鹢翩翩，灵龟隐隐下前浦。","忍回首、佳人渐远，想高城、隔烟树。","几许。","秦楼永昼，谢阁连宵奇遇。","算赠笑千金，酬歌百琲，尽成轻负。","南顾。","念吴邦越国，风烟萧索在何处。","独自个、千山万水，指天涯去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-166","tags":[]},{"id":"poem-3cc7c02d39fe1502893a3418","title":"奉和幸白鹿观应制","author":"赵彦昭","dynasty":"唐","verses":["云骖驱半景，星跸坐中天。","国诞玄宗圣，家寻碧落仙。","玉杯鸾荐寿，宝算鹤知年。","一覩光华旦，欣承道德篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d178343f-1985-47e9-b36b-4887a7659429","tags":[]},{"id":"poem-3cd0a69b99e54b910ca23b47","title":"三年冬大礼五首 三","author":"曹唐","dynasty":"唐","verses":["太一天坛降紫君，属车龙鹤夜成群。","春浮玉藻寒初落，露拂金茎曙欲分。","三代乐回风入律，四溟歌驻水成文。","千官不动旌旗下，日照南山万树云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0e7f2b31-b1e2-4579-a77d-e038dd8512d7","tags":[]},{"id":"poem-3cd0d9728efbefc139ac1ea8","title":"挽辞 一","author":"后主煜","dynasty":"唐","verses":["珠碎眼前珍，花凋世外春。","未销心里恨，又失掌中身。","玉笥犹残药，香匳已染尘。","前哀将后感，无泪可沾巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-018cab44-8167-40eb-8934-09667eb405da","tags":[]},{"id":"poem-3cd22ee3c524b13004f1f16a","title":"春草","author":"曹松","dynasty":"唐","verses":["不独满池塘，梦中佳句香。","春风有余力，引上古城墙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c76a81f0-8853-4e1e-b053-bcce57a84681","tags":[]},{"id":"poem-3cd55a8a9b5fcafc4fe68084","title":"刁景纯学士寄示嘉篇述前后过颍游览之乐不鄙虚陋曲蒙推奖感叹不足辄用本韵通成五十仰答来贶","author":"苏颂","dynasty":"宋","verses":["昔岁寓文馆，雅志慕藩屏。","尝闻近畿州，胜绝惟南颍。","十年走京华，官局苦闲冷。","欲求一麾去，数奏囊章请。","适会择兹守，乘时窃侥幸。","君相宠儒林，念久贷諐眚。","旋蒙左符赐，上戴天恩并。","扁舟促行役，洪渠逐奔猛。","飘然离尘嚣，有若出机穽。","从容光景多，历览江山迥。","去都时值秋，到官月逢寎。","此邦信名区，民愿俗无警。","昔守皆巨公，今犹蒙镇靖。","非才偶承乏，继治实多幸。","前贤有规模，遇事见要领。","因此颇闲暇，得以探物景。","溪湖绕郡郭，台榭跨冈岭。","春媚花百名，秋香荷十顷。","野色连莽苍，水容迷渌浄。","虹驾逵路长，鹢泛源流永。","幽寻穷胜处，登陟疲足胫。","适意自留连，对人成诧逞。","是时汴流阻，北客多过境。","景纯罢山阴，前旆亦南骋。","予逢丈人行，再拜肃襟袊。","君待同舍生，抗礼均侪等。","公斋荐具薄，主席奉陪鼎。","馈以清淮鱼，报我龙山茗。","西园复追从，继日承音謦。","胸怀坦而夷，不事畦与町。","杯盘命镌简，丝竹烦正订。","横管教吹羌，新声赏歌郢。","善谑剧笑谐，尽欢忘醉醒。","自兹别经秋，多故值忧梗。","七月会同轨，远臣伤吊影。","交旧少经涂，酒希但虚皿。","兀然坐空合，何异蛙在井。","故人勤眷盼，尺书询动静。","新诗三百言，斫句露锋颖。","念旧起悲伤，曾游皆记省。","眷予忝畴曩，被爱逾踵顶。","感嘅知己心，中藏聊自儆。","景纯书阁老，二纪酬申丙。","当年文雅誉，久合登西省。","心贪为郡乐，旌旄屡操秉。","徊翔成淹留，前辈今谁并。","复闻乞淮藩，早已饰归艇。","南河如可棹，北渡时引颈。","溪亭待清扫，宾具重消整。","还当揖前尘，晤语慰悬耿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-c968bf4f-0d8b-4335-91b8-5e118136358b","tags":[]},{"id":"poem-3ce0854abe112b33a09ed122","title":"敦煌廿咏（并序） 十二、安城祅咏[二六]","author":"敦煌人作品[一]","dynasty":"唐","verses":["版筑安城日，神祠与此兴。","一州祈景祚，万类仰休征。","苹藻来（釆）无乏，精灵若有凭。","更看云祭处，朝夕酒如绳（渑）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1b069a77-e2b1-4faa-877c-3815300144d8","tags":[]},{"id":"poem-3ce79095eaab4983f7475713","title":"和择之福岩回望岳市","author":"张栻","dynasty":"宋","verses":["回首尘寰去渺然，山中别是一风烟。","好乘晴色上高顶，要看清霜明月天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2f8e8d55-1c97-46e1-a32f-d804bd9099a7","tags":[]},{"id":"poem-3ced74c75c7b8262cb555554","title":"胡捣练","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["伤风化，乱纲常，萱亲逼嫁富家郎。","若把身名辱污了，不如一命丧长江。","［投江介。","丑上救旦下］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8209","tags":[]},{"id":"poem-3cfe04595039904222c64e31","title":"风雨看舟前落花戏为新句","author":"杜甫","dynasty":"唐","verses":["江上人家桃树枝，春寒细雨出疎篱。","影遭碧水潜勾引，风妒红花却倒吹。","吹花困癫傍舟檝，水光风力俱相怯。","赤憎轻薄遮入怀，珍重分明不来接。","湿久飞迟半日高，萦沙惹草细于毛。","蜜蜂蝴蝶生情性，偷眼蜻蜓避百劳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-32c6a206-1a90-452e-a032-19a7665bceba","tags":[]},{"id":"poem-3cfff4c6cd4105b11ab45b4b","title":"独坐敬亭山","author":"李白","dynasty":"唐","verses":["众鸟高飞尽，孤云独去闲。","相看两不厌，只有敬亭山。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-獨坐敬亭山","tags":[]},{"id":"poem-3d07f9581897f5835be4df10","title":"送远曲","author":"张籍","dynasty":"唐","verses":["戏马台南山簇簇，山边饮酒歌别曲。","行人醉后起登车，席上回尊劝僮仆。","青天漫漫覆长路，远游无家安得住。","愿君到处自题名，他日知君从此去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6a91a995-8301-4000-a129-d93c9224852e","tags":["送别","友情"]},{"id":"poem-3d09d3437bda62f1b2520e2c","title":"献诗（题拟）","author":"李夷邺","dynasty":"唐","verses":["偶忆昔年逢上巳，轻舟柳岸宴群臣。","人间蹇薄时提叹，天上风光日日新。","玉帛已来诸国瑞，瑶池固有万年春。","赋诗饮酒平生事，肠断金门愿再亲。","（见《江南余载》卷下。","）（《江南余载》：李夷邺者，前唐诸孙，嗜酒不羁。","保大初，以宗室贤才拜正卿，累经左降，逾年辄复旧官。","元宗上巳开宴，夷邺不在召中，乃献诗曰云云。","上赐御札曰：「我家有外狂宗正，快哉！」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5a757991-76ec-4b08-854d-b8ad7ba25ce0","tags":[]},{"id":"poem-3d1c689ea8bc32ac03bad430","title":"岁暮归南山","author":"孟浩然","dynasty":"唐","verses":["北阙休上书，南山归敝庐。","不才明主弃，多病故人疎。","白发催年老，青阳逼岁除。","永怀愁不寐，松月夜窗虚。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-542cb326-1037-4bd9-b0f6-6479d165dc4c","tags":["唐诗三百首","抒情","失意"]},{"id":"poem-3d1daf3130db2e85ccb2e208","title":"浙东陪元相公游云门寺","author":"赵嘏","dynasty":"唐","verses":["松下山前一径通，烛迎千骑满山红。","溪云乍歛幽岩雨，晓气初高大斾风。","小槛宴花容客醉，上方看竹与僧同。","归来吹尽严城角，路转横塘乱水东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5b6e8726-4351-4c95-b2a1-450b20181604","tags":[]},{"id":"poem-3d1ebe46b8a626f464f770b3","title":"西溪冬夜","author":"曾协","dynasty":"宋","verses":["并堤松柏与云齐，月夜青山一望低。","山鸟不惊人迹绝，步随流水到前溪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9196686b-cded-41b4-8256-722fb776418f","tags":[]},{"id":"poem-3d27a651a47c09f53987f11a","title":"踏莎行·旋葺荒园","author":"张孝祥","dynasty":"宋","verses":["旋葺荒园，初开小径。","物华还与东风竞。","曲槛晖晖落照明，高城冉冉孤烟暝。","柳色金寒，梅花雪静。","道人随处成幽兴。","一杯不惜小淹留，归期已理沧浪艇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-266","tags":[]},{"id":"poem-3d2d27725796d9dba8085f13","title":"古劒池","author":"来鹄","dynasty":"唐","verses":["秋水莲花三四枝，我来慷慨步迟迟。","不决浮云斩邪佞，直成龙去欲何为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bfc49d49-4140-4650-b28f-1de9792fdde7","tags":[]},{"id":"poem-3d2e0ea40f29091c41d39569","title":"渔家傲·小雨廉纤风细细","author":"朱服","dynasty":"宋","verses":["小雨廉纤风细细。","万家杨柳轻烟里。","恋树湿花飞不起。","愁无比。","和春付与西流水。","九十光阴能有几。","金龟解尽留无计。","寄语东城沽酒市。","拼一醉。","而今乐事他年泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-64","tags":["宋词三百首"]},{"id":"poem-3d471e6982ebb3d288f72f21","title":"奉和御制烟","author":"徐铉","dynasty":"宋","verses":["春晴纤霭映斜阳，羃羃偏能覆水乡。","浓似庆云同馥郁，薄如轻素自飞扬。","堤横新柳真成画，楼对遥山正好望。","谁见朝元香案上，龙旗交影共腾骧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-91d1e460-ed78-4a00-a257-5f974bc7a74b","tags":[]},{"id":"poem-3d549f2b9c507f002920f34c","title":"蓦山溪·冰清玉映","author":"仲并","dynasty":"宋","verses":["冰清玉映，自是闺房秀。","十里卷朱帘，好紫陌、家家未有。","天然情素，高压一城春，花艳丽，月精神，梅韵腰枝瘦。","曲屏虚幌，枉著鸳鸯绣。","不是不相逢，泪空滴、年年别袖。","从他兰菊，秋露与春风，终不似，玉人人，一片心长久。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-199","tags":[]},{"id":"poem-3d7b2038e54eba6b9bdda04f","title":"蓼萧","author":"佚名","dynasty":"先秦","verses":["蓼彼萧斯，零露湑兮。既见君子，我心写兮。燕笑语兮，是以有誉处兮。","蓼彼萧斯，零露瀼瀼。既见君子，为龙为光。其德不爽，寿考不忘。","蓼彼萧斯，零露泥泥。既见君子，孔燕岂弟。宜兄宜弟，令德寿岂。","蓼彼萧斯，零露浓浓。既见君子，鞗革忡忡。和鸾雍雍，万福攸同。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-172","tags":[]},{"id":"poem-3d7c3af95e6c2355c040617f","title":"守岁","author":"太宗皇帝","dynasty":"唐","verses":["暮景斜芳殿，年华丽绮宫。","寒辞去冬雪，暖带入春风。","阶馥舒梅素，盘花卷烛红。","共欢新故岁，迎送一宵中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-95db82fe-9e50-4bc6-be79-d1c79c61ce32","tags":["闲适","春节"]},{"id":"poem-3d85728a96056672d2b7e969","title":"南乡子·乘彩舫","author":"李珣","dynasty":"五代","verses":["乘彩舫，过莲塘，棹歌惊起睡鸳鸯。","游女带香偎伴笑，争窈窕，竞折团荷遮晚照。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-28","tags":[]},{"id":"poem-3d86149326c0a14a8c5d264b","title":"望江南・忆江南·玄珠降","author":"陈朴","dynasty":"宋","verses":["玄珠降，丹窟在中宫。","九候息调重九数，赤波忽迸太阳东。","心肾始交通。","逢六变，重六息阴功。","火自海门朝帝坐，水从莲沼佐丁公。","紫电透玲珑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-961","tags":[]},{"id":"poem-3d9237a1cae1cfc7cd91c518","title":"咏史","author":"徐九臯","dynasty":"唐","verses":["亡国秦韩代，荣身刘项年。","金槌击政后，玉斗碎增前。","圣主称三杰，明离保四贤。","已申黄石祭，方慕赤松仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1ab1c514-5415-4e59-9139-bf6b53c4ae54","tags":[]},{"id":"poem-3d95f5839da36f8f9c758ec7","title":"喜雨再用前韵","author":"王十朋","dynasty":"宋","verses":["南国久无雨，渴心欲生埃。","麦既枯且死，木亦黄而摧。","方春云已火，未夏蚊成雷。","刺史固有罪，斯民自宜哀。","真人及大士，久出应思回。","闭阳纵诸阴，愧无董生才。","林鸠厌呼唤，石燕徒低徊。","有日上扶桑，无云起阳台。","方修九渊祀，遽闻尺木催。","想惊阿香梦，疑噀栾巴杯。","夜中簷溜响，枕上愁颜开。","愿遍普天下，不止泉山隈。","莫作鼎湖浪，因风下崔嵬。","明朝贺雨诗，定自莆中来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b92fc8bd-8374-42df-8ccc-917d3fc8f983","tags":[]},{"id":"poem-3d9cd61aec4c1f0c53c28350","title":"夜游曲","author":"郑愔","dynasty":"唐","verses":["汉室欢娱盛，魏国文雅遒。","许史多暮宿，应陈从夜游。","西园䜩公子，北里召王侯。","讵似将军猎，空嗟亭尉留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-79031f67-be20-4ef3-b01a-60eb5f5ea925","tags":[]},{"id":"poem-3da153310d25345048f8c627","title":"相鼠","author":"佚名","dynasty":"先秦","verses":["相鼠有皮，人而无仪！人而无仪，不死何为？","相鼠有齿，人而无止！人而无止，不死何俟？","相鼠有体，人而无礼，人而无礼！胡不遄死？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-51","tags":[]},{"id":"poem-3da4796e95807cf47695cf89","title":"没了期歌 一","author":"吴越王钱镠","dynasty":"唐","verses":["没了期，没了期，营基才了又仓基。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ba8a1004-e3bc-4167-93e6-1adc22d3eedb","tags":[]},{"id":"poem-3da56827b29d2f891cc74e22","title":"喜迁莺·街鼓动","author":"韦庄","dynasty":"五代","verses":["街鼓动，禁城开，天上探人回，凤衔金榜出云来，平地一声雷。","莺已迁，龙已化，一夜满城车马。家家楼上簇神仙，争看鹤冲天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-13","tags":[]},{"id":"poem-3da573806f4193a6dec7db9d","title":"宿齐山僧舍","author":"张乔","dynasty":"唐","verses":["一宿经窗卧白波，万重归梦隔烟萝。","若言不得南宗要，长在禅床事更多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b9b71b83-daeb-4af4-a4b6-7683d664fd88","tags":[]},{"id":"poem-3da7556de42253642563b97c","title":"摊破浣溪沙·菡萏香销翠叶残","author":"李璟","dynasty":"五代","verses":["菡萏香销翠叶残，西风愁起绿波间。","还与韶光共憔悴，不堪看！","细雨梦回鸡塞远，小楼吹彻玉笙寒。","多少泪珠无限恨，倚栏杆。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-3","tags":[]},{"id":"poem-3dc6ccb0d10fa0b400abad8e","title":"清平调词三首 二","author":"李白","dynasty":"唐","verses":["一枝秾艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-99167d13-8e2c-4b75-bf93-62b0682dfdd0","tags":["女子","近代曲辞","唐诗三百首","乐府"]},{"id":"poem-3dcf7447ee37a93b6adaceb0","title":"九歌·少司命","author":"屈原","dynasty":"先秦","verses":["秋兰兮麋芜，罗生兮堂下。","绿叶兮素华，芳菲菲兮袭予。","夫人兮自有美子，荪何以兮愁苦。","秋兰兮青青，绿叶兮紫茎。","满堂兮美人，忽独与余兮目成。","入不言兮出不辞，乘回风兮载云旗。","悲莫悲兮生别离，乐莫乐兮新相知。","荷衣兮蕙带，儵而来兮忽而逝。","夕宿兮帝郊，君谁须兮云之际。","与女沐兮咸池，曦女发兮阳之阿。","望美人兮未来，临风怳兮浩歌。","孔盖兮翠旌，登九天兮抚彗星。","竦长剑兮拥幼艾，荪独宜兮为民正。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-6","tags":[]},{"id":"poem-3dd1bb5a975fb17a21b527d3","title":"水壁","author":"华镇","dynasty":"宋","verses":["画手闻曹霸，伊人岂裔孙。","穷神邈江海，遗迹在墙垣。","发地惊涛起，扶椽叠浪翻。","来非自胥怒，去不为鲸吞。","咫尺重渊险，寻常万里奔。","气疑烝宇宙，势欲浸乾坤。","但见挥长笔，谁能测巨源。","汪洋须骇瞩，漥突几惊扪。","湛湛将澄处，悠悠叠细痕。","轻飔掠伊洛，阔岸漫湘沅。","怒势功尤壮，飞澜地欲掀。","沧溟拥神岛，穷发运游鹍。","槃礴应无顾，安排自有门。","夙成参造化，无用契胚浑。","岁久人虽远，尘侵墨未昏。","依稀逢海若，仿佛吊湘魂。","倦客萦多累，乘桴特未援。","时来观浩荡，聊用涤尘烦。","莫使蜗涎蠹，常令墨妙存。","不劳浮渤澥，已似陟昆仑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-788dcfa4-1193-4533-a901-067bbbd339e3","tags":[]},{"id":"poem-3dd1fcbabcee6da71c1895c8","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十","author":"易静","dynasty":"唐","verses":["月奇合，生门见九天。","祭祷神祇行圣术，布仇（辛本、川本作「筹」）作法此间言，神遁不虚传。","（生门月奇合，得九天所临之位，谓「神遁」。","宜作布筹，行圣术，祭神祇。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-20ccb075-bd23-4a9e-a0a9-648a5f252e22","tags":[]},{"id":"poem-3dd26ae8f5d5a2805dbd530f","title":"书怀寄元郎中","author":"张籍","dynasty":"唐","verses":["转觉人间无气味，常因身外省因缘。","经过独爱游山客，计校唯求买药钱。","重作学官闲尽日，一离江坞病多年。","吟君钓客词中说，便欲南归榜小船。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-df014f30-57b2-4a82-b2be-efa446d5f926","tags":[]},{"id":"poem-3dd29daa0fb90933449aa5cc","title":"和俞几先喜雨二首  其一","author":"曾协","dynasty":"宋","verses":["万人望岁正艰难，坐对盘餐泚在颜。","沿溯谩谈舟楫利，圃畦未放桔槹闲。","欢呼甘雨今朝足，准拟丰年旧观还。","眼里尘氛扫除尽，扑人空翠绕西山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-dd47ca79-4b57-47d4-9be1-16a22c327575","tags":[]},{"id":"poem-3dd2a18d3b929d0e356e7829","title":"万桂堂","author":"王十朋","dynasty":"宋","verses":["佛国新开选佛场，蟾宫分桂十千章。","邦人种德家家熟，仙籍题名叶叶香。","地占清光一轮满，门传盛事五枝芳。","东堂万万高攀手，莫负君恩与义方。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d92d31e2-9cf9-41c3-bcd2-3b26797084fd","tags":[]},{"id":"poem-3de126f58f8ba0cb856d8ef4","title":"三游巾子山寺感述","author":"任翻","dynasty":"唐","verses":["清秋绝顶竹房开，松鹤何年去不回。","惟有前峰明月在，夜深犹过半江来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-28b2104f-d0ca-46e5-af36-f99951136d3a","tags":[]},{"id":"poem-3de14d9b1ae8e82fa4165456","title":"奉赠宣抚孟参政二首  其二","author":"李纲","dynasty":"宋","verses":["睢阳一别五经春，邂逅相逢瘴海滨。","华髪知公因国事，苍颜顾我久埃尘。","绨袍念旧故人意，药裹关心多病身。","入觐从容见知旧，为言秪欲老垂纶。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ce699dec-403d-48ea-b860-c0f9ee8d2335","tags":[]},{"id":"poem-3de38e9d04d49016f68c2cfd","title":"洋川 二","author":"和凝","dynasty":"唐","verses":["自陪台旆到洋川，两载优游汉水边。","（同前。","）（按：《全唐诗》卷七三五以「华夷」、「官闲」二联为七绝一首，系据《唐音戊签余》四转录，后者又系辑自宋祝穆《方舆胜览》卷六八。","今据《舆地纪胜》所载及诗律推之，原诗当为七律，颔联二句已佚。","《全唐诗续补遗》卷十四将「自陪」二句接于「官闲」四句前，实误，今重录之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-284fdf24-d14b-46d2-9218-6b84944cd2f5","tags":[]},{"id":"poem-3df0867dcedf4b2010c2b43e","title":"和明叔游白龙溪","author":"司马光","dynasty":"宋","verses":["溪深荒径微，寻胜不知疲。","寒月影随马，晓风冰满髭。","行歌被褐叟，聚戏拾薪儿。","外野饶真趣，令人怀抱夷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-268a484e-4a5e-4926-ad1f-643d56be721f","tags":[]},{"id":"poem-3df511d58e268dfaad0645ae","title":"平台夜遇李景参有别","author":"高适","dynasty":"唐","verses":["离心忽怅然，策马对秋天。","孟诸薄暮凉风起，归客相逢渡睢水。","昨时携手已十年，今日分途各千里。","岁物萧条满路岐，此行浩荡令人悲。","家贫羡尔有微禄，欲往从之何所之。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-203b10c7-2886-4ae6-870f-6eb1ec9ff558","tags":[]},{"id":"poem-3df74a6d936f338023515a13","title":"过马当","author":"徐凝","dynasty":"唐","verses":["风波隐隐石苍苍，送客灵鸦拂去樯。","三月尽头云叶秀，小姑新著好衣裳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8691918b-6845-4472-be12-e5173044f98c","tags":[]},{"id":"poem-3dfa2e023155fcd3c8b86e8f","title":"寄友人","author":"刘得仁","dynasty":"唐","verses":["风飒沈思眼忽开，尘埃污得是庸才。","那堪更见巢松鹤，飞入青云不下来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8ae6c860-b5be-4270-ad3b-a57fcf7be7b0","tags":[]},{"id":"poem-3dffba1e56a12e2e5a79b23f","title":"宿江店","author":"张籍","dynasty":"唐","verses":["野店临西浦，门前有橘花。","停灯待贾客，卖酒与渔家。","夜静江水白，路回山月斜。","闲寻泊船处，潮落见平沙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-89c302eb-ba2e-41eb-ba00-12993d2db718","tags":[]},{"id":"poem-3e039a726fafb557bf0cac56","title":"於潜尉陈时斋获贼","author":"释居简","dynasty":"宋","verses":["小队气晶晶，平常白面生。","沈冤资大勇，凶胆折先声。","山鬼晨犹寐，隣厖夜不惊。","历阳穷少府，此话恐难并。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-e5f9c72d-95e0-46c7-8c8b-023ee9b49af7","tags":[]},{"id":"poem-3e0c019ec84aaf10d4bc7ad5","title":"旅次夏州","author":"马戴","dynasty":"唐","verses":["嘶马发相续，行次夏王台。","锁郡云阴暮，鸣笳烧色来。","霜繁边上宿，鬓改碛中回。","怅望胡沙晓，惊蓬朔吹催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4ae2c08a-704a-4475-8b4b-55ed39167cc5","tags":[]},{"id":"poem-3e1b173ddbfda47450b1d211","title":"九月九日上幸慈恩寺登浮图群臣上菊花寿酒","author":"上官昭容","dynasty":"唐","verses":["帝里重阳节，香园万乘来。","却邪萸入佩，献寿菊传杯。","墖类承天涌，门疑待佛开。","睿词悬日月，长得仰昭回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-81981192-77b7-407d-ab89-18ebf00d8de4","tags":[]},{"id":"poem-3e1df58e52b8ed33b01b5e82","title":"巷伯","author":"佚名","dynasty":"先秦","verses":["萋兮斐兮，成是贝锦。彼谮人者，亦已大甚！","哆兮侈兮，成是南箕。彼谮人者，谁适与谋。","缉缉翩翩，谋欲谮人。慎尔言也，谓尔不信。","捷捷幡幡，谋欲谮言。岂不尔受？既其女迁。","骄人好好，劳人草草。苍天苍天，视彼骄人，矜此劳人。","彼谮人者，谁适与谋？取彼谮人，投畀豺虎。豺虎不食，投畀有北。有北不受，投畀有昊！","杨园之道，猗于亩丘。寺人孟子，作为此诗。凡百君子，敬而听之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-199","tags":[]},{"id":"poem-3e277ba1eb8695f90392975c","title":"菁菁者莪","author":"佚名","dynasty":"先秦","verses":["菁菁者莪，在彼中阿。既见君子，乐且有仪。","菁菁者莪，在彼中沚。既见君子，我心则喜。","菁菁者莪，在彼中陵。既见君子，锡我百朋。","泛泛杨舟，载沉载浮。既见君子，我心则休。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-175","tags":[]},{"id":"poem-3e2c5ee499b6f6ce0e8a5932","title":"嘉州作","author":"杨徽之","dynasty":"宋","verses":["俗遇腊辰持药献，吏逢衙日隔花参。","耆宿因来问封部，竹篱西畔是云南。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c9217b2a-7467-402e-90bb-072f5ab9f30f","tags":[]},{"id":"poem-3e2c624e6e38a7113a044fb7","title":"唐大飨拜洛乐章 昭和","author":"则天皇后","dynasty":"唐","verses":["九玄眷命，三圣基隆。","奉成先旨，明台毕功。","宗祀展敬，冀表深衷。","永昌帝业，式播淳风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b838cc4b-fb09-4800-8a2b-e2de4ed1441a","tags":[]},{"id":"poem-3e2c7c45fb6803bea05a2d2f","title":"浣溪沙·兰沐初休曲槛前","author":"孙光宪","dynasty":"五代","verses":["兰沐初休曲槛前，缓风迟日洗头天，湿云新敛未梳蝉。","翠袂半将遮粉臆，宝钗长欲坠香肩，此时模样不禁怜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-42","tags":[]},{"id":"poem-3e315fa312dbcdc8dd53e23c","title":"游长宁公主流杯池二十五首 十三","author":"上官昭容","dynasty":"唐","verses":["策杖临霞岫，危步下霜蹊。","志逐深山静，途随曲涧迷。","渐觉心神逸，俄看云雾低。","莫怪人题树，祗为赏幽栖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-202f8187-f247-41cc-84dc-29c91d4ba11c","tags":[]},{"id":"poem-3e33e7226e177e20e4207378","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 四","author":"易静","dynasty":"唐","verses":["乙丙丁，名曰是三奇。","天上若临三吉路，自然神助合天机，任（辛本、川本作「恁」）往莫忧疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6aed96a1-1366-4b89-a56f-77cf3b2ab346","tags":[]},{"id":"poem-3e3bb7fee31b2e9943c60e8f","title":"浣溪沙·蝶粉蜂黄大小乔","author":"吴文英","dynasty":"宋","verses":["蝶粉蜂黄大小乔。","中庭寒尽雪微销。","一般清瘦各无聊。","窗下和香封远讯，墙头飞玉怨邻箫。","夜来风雨洗春娇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-448","tags":[]},{"id":"poem-3e3bc1347e0a0c745bdd29fb","title":"赠雍陶博士","author":"刘得仁","dynasty":"唐","verses":["腹是群书笥，官为六义师。","情高少尘事，朝下足闲时。","有句同人伏，无私胄子知。","汉庭公议在，正与触邪宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-671f169b-74f0-4341-9794-b56981663920","tags":[]},{"id":"poem-3e3c7d3d1d0b9c206f8fe667","title":"春恨三首 三","author":"钱珝","dynasty":"唐","verses":["永巷频闻小苑游，旧恩如泪亦难收。","君前愿报新颜色，团扇须防白露秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-97778acd-7c68-44ef-b330-98dd0ed1b2fc","tags":[]},{"id":"poem-3e4701c59c9001dc11305404","title":"横吹曲辞 折杨柳 一","author":"孟郊","dynasty":"唐","verses":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c8e50d0a-dd19-4fa2-b07e-95882090e9d7","tags":[]},{"id":"poem-3e506e3cda842b13d652c73a","title":"贺王起","author":"广宣","dynasty":"唐","verses":["从辞凤阁掌丝纶，便向青云领贡宾。","再辟文场无枉路，两开金榜绝冤人。","眼看龙化门前水，手放莺飞谷口春。","明日定归台席去，鹡鸰原上共陶钧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2d051af0-83ac-4799-ae24-b0486d3aaf22","tags":[]},{"id":"poem-3e5236c1cf55cc84b68705bd","title":"阮郎归·豪家大厦敞千楹","author":"张抡","dynasty":"宋","verses":["豪家大厦敞千楹。","风摇玉柄轻。","金盆弄水复敲冰。","热从何处生。","低草舍，小茅亭。","如何安此身。","元来一念静无尘。","萧然心自清。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-907","tags":[]},{"id":"poem-3e59051f1920dbf9ad7de239","title":"梁公子","author":"李贺","dynasty":"唐","verses":["风彩出萧家，本是菖蒲花。","南塘连子熟，洗马走江沙。","御牋银沫冷，长簟凤窠斜。","种柳营中暗，题书赐馆娃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b0a06901-b758-4f7c-858a-31cd2039db1f","tags":[]},{"id":"poem-3e5f281899b7282aa54bfe07","title":"九江琵琶亭","author":"宋敏求","dynasty":"宋","verses":["夜泊浔阳宿酒楼，琵琶亭畔荻花秋。","云沈鸟没事已往，月白风清江自流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cceeb0a9-7e05-41f5-834a-ae3270473855","tags":[]},{"id":"poem-3e628beb4d140f525e6c269b","title":"郊庙歌辞  善胜舞","author":"不详","dynasty":"唐","verses":["圣祖累功，福钟来裔。","持羽执干，舞文不废。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-42500782-6469-41ae-aeae-ecaba64511e1","tags":[]},{"id":"poem-3e68f4cf8537ee3ed391a760","title":"山居八咏 六","author":"常达","dynasty":"唐","verses":["古寺凭栏危，时闻举妙机。","庭空月色净，夜迥磬声移。","漏转寒更急，灯残冷焰微。","太虚同万象，相谓话玄微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1bb5c14d-2f3c-4f4c-b66f-819ff4b2d23a","tags":[]},{"id":"poem-3e70ea3924b0105b1a32b214","title":"临江仙·樱桃落尽春归去","author":"李煜","dynasty":"五代","verses":["樱桃落尽春归去，蝶翻轻粉双飞。","子规啼月小楼西。","玉钩罗幕，惆怅暮烟垂。","别巷寂寥人散后，望残烟草低迷。","炉香闲袅凤凰儿。","空持罗带，回首恨依依。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-8","tags":[]},{"id":"poem-3e79218b9228ca80abef8777","title":"谒寇忠愍祠堂六首  其四","author":"李纲","dynasty":"宋","verses":["平生爱看柘枝舞，宾燕多余密炬堆。","富贵在公真末事，谁云缘此故南来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2960d643-285d-4b6d-a13a-10f4032a1437","tags":[]},{"id":"poem-3e8aee87761eb7f4d30aa1be","title":"酬藤杖","author":"张籍","dynasty":"唐","verses":["病里出门行步迟，喜君相赠古藤枝。","倚来自觉身生力，每向傍人说得时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ecd41f12-a61f-4c5e-8cce-5289695e52d3","tags":[]},{"id":"poem-3e8d62dde4e55a4a7959a46c","title":"鹧鸪天·枕簟溪堂冷欲秋","author":"辛弃疾","dynasty":"宋","verses":["枕簟溪堂冷欲秋。","断云依水晚来收。","红莲相倚浑如醉，白鸟无言定自愁。","书咄咄，且休休。","一丘一壑也风流。","不知筋力衰多少，但觉新来懒上楼。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-210","tags":["宋词三百首"]},{"id":"poem-3e8fcbd6fd6de698f701c79e","title":"临江仙·雨停荷芰逗浓香","author":"阎选","dynasty":"五代","verses":["雨停荷芰逗浓香，岸边蝉噪垂杨。","物华空有旧池塘，不逢仙子，何处梦襄王。","珍簟对欹鸳枕冷，此来尘暗凄凉。","欲凭危槛恨偏长，藕花珠缀，犹似汗凝妆。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-21","tags":[]},{"id":"poem-3e99604df464e60384bf5970","title":"郊庙歌辞 仪坤庙乐章 迎神","author":"不详","dynasty":"唐","verses":["月灵降德，坤元授光。","娥英比秀，任姒均芳。","瑶台荐祉，金屋延祥。","迎神有乐，歆此嘉芗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f9531bb3-bce8-42e3-9e73-28de161c2b1a","tags":[]},{"id":"poem-3ea4868a0ed1a6a4f6178df1","title":"句 四","author":"罗隐","dynasty":"唐","verses":["马上抱鸡鬬三市，袖中携剑五陵游。","（《荛山堂》。","以上六句均见明闵元衢《罗江东外纪》。","）（按：自《下第诗》以降，皆据雍文华校点本《罗隐集》所辑佚句迻录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-277b6d07-84d6-4cf2-b7be-1b56ff5e0432","tags":[]},{"id":"poem-3ea509bc0af5b30e9e2f240a","title":"西江月·青锦缠条配剑","author":"谢逸","dynasty":"宋","verses":["青锦缠条配剑，紫丝络辔飞骢。","入关意气喜生风。","年少胸吞云梦。","金阙日高露泣，东华尘软香红。","争看荀氏第三龙。","春暖桃花浪涌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-607","tags":[]},{"id":"poem-3ea55e011a4f1887f0b218e9","title":"戏赠张五弟𬤇三首 一","author":"王维","dynasty":"唐","verses":["吾弟东山时，心尚一何远。","日高犹自卧，钟动始能饭。","领上髪未梳，床头书不卷。","清川兴悠悠，空林对偃蹇。","青苔石上净，细草松下软。","窗外鸟声闲，阶前虎心善。","徒然万象多，澹尔太虚缅。","一知与物平，自顾为人浅。","对君忽自得，浮念不烦遣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-076b8da6-83c1-41dc-8893-13425a6dc1e8","tags":[]},{"id":"poem-3ea914cf0ba70ab45bef2158","title":"偈颂七十一首  其五八","author":"释了惠","dynasty":"宋","verses":["仲冬严寒年年事，须知事上大有事。","若人知得事上事，到了全然不干事。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-36959672-6081-489f-9a82-bb08c089e8ad","tags":[]},{"id":"poem-3eb028fb9ad136aa79914939","title":"送别驾赴晋陵即舍人叔之兄","author":"李端","dynasty":"唐","verses":["诸宗称叔父，从子亦光辉。","谢脁中书直，王祥别乘归。","江帆冲雨上，海树隔潮微。","南阮贫无酒，唯将泪湿衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0f2f5bed-450c-40f4-b45c-4838badedf18","tags":[]},{"id":"poem-3eb1836c9d9874a79bab9c59","title":"蜀相","author":"杜甫","dynasty":"唐","verses":["丞相祠堂何处寻，锦官城外柏森森。","映堦碧草自春色，隔叶黄鹂空好音。","三顾频烦天下计，两朝开济老臣心。","出师未捷身先死，长使英雄泪满襟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a353dcb1-12cc-4ca8-af1e-55d1d62445f8","tags":["唐诗三百首","隋・唐・五代","七言律诗","忧国忧民","写人","咏史怀古","赞颂"]},{"id":"poem-3ebbecb38ecf4cb0f5d027fc","title":"和长安郭明府与友人县中会饮","author":"张籍","dynasty":"唐","verses":["一尊清酒两人同，好在街西水县中。","自恨病身相去远，此时闲坐对秋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0c499a93-bbd0-406b-a428-7bfe13f77626","tags":[]},{"id":"poem-3ebe3c9f6f4ecd7dd1bcd874","title":"寄梅处士","author":"张籍","dynasty":"唐","verses":["扰扰人间是与非，官闲自觉省心机。","六行班里身常下，九列符中事亦稀。","市客惯曾赊贱药，家僮惊见著新衣。","君今独得居山乐，应喜多时未办归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-599ee7ca-7e82-4689-b92a-709e51bfce33","tags":[]},{"id":"poem-3ec2150207be5bb14275d279","title":"送方岩出帅平峒寇  其二","author":"释居简","dynasty":"宋","verses":["漠漠江城度柳花，江南春事又天涯。","绿抽秧颖秋占稼，碧凝檀云晚未衙。","风动十连咸自化，夜严千灶静无哗。","书生只事毛锥子，试把轻裘缓带夸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b9b2b4b0-c476-45a0-bed9-766ddac81380","tags":[]},{"id":"poem-3ec933834acf528322bb07fb","title":"送人归黔府","author":"司空曙","dynasty":"唐","verses":["伏波箫鼓水云中，长戟如霜大斾红。","油幕晓开飞鸟绝，翩翩上将独趋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2fea3769-7cab-4c8d-9a7b-5a9d654b9573","tags":[]},{"id":"poem-3ed0af08717647dbfbecd69c","title":"饮修仁茶","author":"李纲","dynasty":"宋","verses":["北苑龙团久不尝，修仁茗饮亦甘芳。","夸研鬭白工夫拙，辟瘴消烦气味长。","江表露芽空绝品，蜀中仙掌可同行。","从容饭罢何为者，一椀还兼一炷香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-12c9f768-92aa-4862-a79b-589536d61be5","tags":[]},{"id":"poem-3ed1b633a4fc519fee6d8fd2","title":"和子华过王帅家见梅花盛开呈君实子骏兼简尧夫","author":"司马光","dynasty":"宋","verses":["去年与客尽清欢，今日重来立马看。","犹是携觞同醉在，只愁风雨横相干。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b634438b-c729-4ece-bb40-b4158140ed00","tags":[]},{"id":"poem-3eed0f2a62b892205f4f15bf","title":"扬之水","author":"佚名","dynasty":"先秦","verses":["扬之水，不流束薪。彼其之子，不与我戍申。怀哉怀哉，曷月予还归哉？","扬之水，不流束楚。彼其之子，不与我戍甫。怀哉怀哉，曷月予还归哉？","扬之水，不流束蒲。彼其之子，不与我戍许。怀哉怀哉，曷月予还归哉？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-67","tags":[]},{"id":"poem-3eee0b35615bf11b2820dd76","title":"九怀·匡机","author":"王褒","dynasty":"汉","verses":["极运兮不中，来将屈兮困穷。","余深愍兮惨怛，愿一列兮无从。","乘日月兮上征，顾游心兮鄗酆。","弥览兮九隅，彷徨兮兰宫。","芷闾兮药房，奋摇兮众芳。","菌阁兮蕙楼，观道兮从横。","宝金兮委积，美玉兮盈堂。","桂水兮潺湲，扬流兮洋洋。","蓍蔡兮踊跃，孔鹤兮回翔。","抚槛兮远望，念君兮不忘。","怫郁兮莫陈，永怀兮内伤。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-38","tags":[]},{"id":"poem-3eef99a641a20a37c9faa614","title":"念奴娇·野棠花落","author":"辛弃疾","dynasty":"宋","verses":["野棠花落，又匆匆、过了青明时节。","地东风欺客梦，一夜云屏寒怯。","曲岸持觞，垂杨系马，此地曾轻别。","楼空人去，旧游飞燕能说。","闻道绮陌东头，行人长见，帘底纤纤月。","旧恨春江流未断，新恨云山千叠。","料得明朝，尊前重见，镜里花难折。","也应惊问，近来多少华发。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-209","tags":["宋词三百首"]},{"id":"poem-3ef0107c34a6f78cd8b1825c","title":"句","author":"陆贽","dynasty":"唐","verses":["遶堦流㶁㶁，来砌树阴阴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-28503959-b22c-4839-bf8f-6afd22bd3842","tags":[]},{"id":"poem-3ef40605f120955c287adc34","title":"送周教授兼简刘左史薛寺丞  其一","author":"释居简","dynasty":"宋","verses":["舍选诸生出，侯藩博士归。","一官甘独冷，千仞看群飞。","苦学丹心古，春风泮水肥。","传衣观岁晚，先使识抠衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9635e1a7-3e1b-4235-8222-fd40429df8e2","tags":[]},{"id":"poem-3ef648027e3c0cfea487d8f0","title":"白髭","author":"刘象","dynasty":"唐","verses":["到处逢人求至药，几回染了又成丝。","素丝易染髭难染，墨翟当时合泣髭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dce6d5a0-b9b3-405d-9d6a-f4bb00c2808c","tags":[]},{"id":"poem-3ef7ab8b5ed57518c35a0e9b","title":"句","author":"马戴","dynasty":"唐","verses":["申胥任向秦庭哭，靳尚终贻楚国忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1deddf71-9ab1-41e2-bb7e-2b86d0400cdf","tags":[]},{"id":"poem-3f041e3b9df1939b24641704","title":"赠孟浩然","author":"李白","dynasty":"唐","verses":["吾爱孟夫子，风流天下闻。","红颜弃轩冕，白首卧松云。","醉月频中圣，迷花不事君。","高山安可仰，徒此揖清芬。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9d1b6a18-571c-4f25-bfdb-3fe260115c3f","tags":["唐诗三百首","赠别","五言律诗","敬爱"]},{"id":"poem-3f0bbb59a11121563f163ca9","title":"积雨辋川庄作","author":"王维","dynasty":"唐","verses":["积雨空林烟火迟，蒸藜炊黍饷东菑。","漠漠水田飞白鹭，阴阴夏木啭黄鹂。","山中习静观朝槿，松下清斋折露葵。","野老与人争席罢，海鸥何事更相疑。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0949fe2a-aadf-4cd4-b1c3-25fcdaecdb96","tags":["唐诗三百首","七言律诗","田园"]},{"id":"poem-3f0e9f83b0d644dd1a67ce0f","title":"韩守松卿索近诗","author":"陈造","dynasty":"宋","verses":["昔人技成叹屠龙，似我五字躭雕虫。","镌肝搯肾探戃恍，半世不辞诗得穷。","诗成颇讶神与力，畴昔梦中分五色。","援毫动作万钧斡，应俗何曾一钱直。","豪韩有句当千年，取世所遗政自贤。","数篇蜚向青眼边，可复把玩盘中圆。","君家十顷围翠密，近榭远亭如画出。","时须唤我一罇同，笑对风烟挥此笔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c39bc501-dfcf-447a-aa43-740f5705d173","tags":[]},{"id":"poem-3f0ecd96bb634d09b9424f6a","title":"咏院中藂竹","author":"吕太一","dynasty":"唐","verses":["擢擢当轩竹，青青重岁寒。","心贞徒见赏，箨小未成竿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b716e76f-6401-4990-b62b-637e59c7fb47","tags":["咏物诗","竹子","咏物","赞美"]},{"id":"poem-3f147728baed03b72bece01a","title":"句","author":"陈商霖","dynasty":"宋","verses":["生死交情谁念旧，炎凉世态竞迎新。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b0fbf556-be69-4fc9-88bb-fe8ff0db2ff5","tags":[]},{"id":"poem-3f191f32ae8cbb1112c14972","title":"六如亭","author":"李纲","dynasty":"宋","verses":["松林葬玉近禅扃，便把伽陀当勒铭。","居士已亡三昧手，侍人空有六如亭。","玉环约指无消息，巫峡行云更杳冥。","万法本来皆梦幻，春风又见草青青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-83d8142b-8a3b-4ecc-b4e7-82f12451886f","tags":[]},{"id":"poem-3f290fb26039d34097d23805","title":"击瓯楼","author":"邵叶","dynasty":"宋","verses":["驻旌元帅遗风在，击缶高人逸兴酣。","水转巴文清溜急，山连蒙岫翠光涵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4b6112b1-65d4-4bf3-b738-b4c8fe511558","tags":[]},{"id":"poem-3f35ddfd66838e2f8652c0cb","title":"春寒","author":"徐凝","dynasty":"唐","verses":["乱雪从教舞，回风任听吹。","春寒能作底，已被柳条欺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f2b846b5-590c-4b5f-b207-b047060fe574","tags":[]},{"id":"poem-3f4c75ecfb2fd7a0f448d026","title":"潜","author":"佚名","dynasty":"先秦","verses":["猗与漆沮，潜有多鱼。有鳣有鲔，鲦鲿鰋鲤。以享以祀，以介景福。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-280","tags":[]},{"id":"poem-3f52b0e25c24079b6cd9b420","title":"梯飚","author":"释居简","dynasty":"宋","verses":["凉腋拊岧嶤，可扪丛玉霄。","一层高步武，千仞拔尘嚣。","明月秦箫断，雕盘古篆消。","天浆几时熟，款曲试芳瓢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-edb8760e-64e6-4a4c-b1d5-e4e07749beba","tags":[]},{"id":"poem-3f54e2bef7409f4f378d129b","title":"鲜于少府宅看花","author":"李端","dynasty":"唐","verses":["谢家能植药，万簇相萦倚。","烂熳绿苔前，婵娟青草里。","垂栏复照户，映竹仍临水。","骤雨发芳香，回风舒锦绮。","孤光杂新故，众色更重累。","散碧出疎茎，分黄成细蘂。","游蜂高更下，惊蝶坐还起。","玉貌对应慙，霞标方不似。","春阴怜弱蔓，夏日同短晷。","回落报荣衰，交关鬬红紫。","花时苟未赏，老至谁能止。","上客屡移床，幽僧劳凭几。","初合虽薄劣，却得陪君子。","敢问贤主人，何如种桃李。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-7ac0a7d0-2347-4647-8165-9dca1bef2530","tags":[]},{"id":"poem-3f58a3d931ecef0bff572581","title":"郡斋卧疾赠昼上人","author":"于𬱖","dynasty":"唐","verses":["夙陪翰墨徒，深论穷文格。","丽则风骚后，公然我词客。","晚依方外友，极理探精赜。","吻合南北宗，昼公我禅伯。","尤明性不染，故我行贞白。","随顺令得解，故我言芳泽。","霅水漾清浔，吴山横碧岑。","含珠复蕴玉，价重双南金。","的皪曜奇彩，凄清流雅音。","商声发楚调，调切谱瑶琴。","吴山为我高，霅水为我深。","万景徒有象，孤云本无心。","众木岂无声，椅桐有清响。","众耳岂不聆，钟期有真赏。","高洁古人操，素怀夙所仰。","觌君冰雪姿，祛我淫滞想。","常吟柳恽诗，苕浦久相思。","逮此远为郡，苹洲芳草衰。","逢师年腊长，值我病容羸。","共话无生理，聊用契心期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d8eb0b45-88ed-475c-afc8-5a7cb868a116","tags":[]},{"id":"poem-3f58abc57e2491355f30705a","title":"次韵郡博士贺龟山祠新成  其一","author":"释居简","dynasty":"宋","verses":["经术修明可保邦，凛然冠佩陈堂堂。","竞传溪上诸贤聚，渐得门前一水香。","疎剪新篁看抱节，诛锄恶草戒侵墙。","美轮美奂从人颂，潜德虽幽愈耿光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-07d14bcb-5548-4771-92fa-fe6ed4e1caf8","tags":[]},{"id":"poem-3f58d54b49a5c682b0af876e","title":"吴门柳・渔家傲·窈窕盘门西转路","author":"贺铸","dynasty":"宋","verses":["窈窕盘门西转路。","残阳映带青山暮。","最是长杨攀折苦。","堪怜许。","清霜翦断和烟缕。","春水归期端不负。","依依照影临南浦。","留取木兰舟少住。","无风雨。","黄昏月上潮平去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-103","tags":[]},{"id":"poem-3f610ad6db4f56ca031ed2bf","title":"喜友人及第","author":"虚中","dynasty":"唐","verses":["碧霄章句绝离手，紫府神仙尽点头。","（均见《吟窗杂录》卷十四正字王玄《诗中旨格》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-84d0d19e-3137-48a5-acb2-62c78ee95096","tags":[]},{"id":"poem-3f61e71fffc4063fbbd09055","title":"郪中感旧","author":"刘象","dynasty":"唐","verses":["顷年曾住此中来，今日重游事可哀。","忆得几家欢宴处，家家家业尽成灰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-63223863-df5d-4277-b245-4cff39f7c87f","tags":[]},{"id":"poem-3f6adf7663407f7bde85a8a8","title":"泮水","author":"佚名","dynasty":"先秦","verses":["思乐泮水，薄采其芹。鲁侯戾止，言观其旗。其旗茷茷，鸾声哕哕。无小无大，从公于迈。","思乐泮水，薄采其藻。鲁侯戾止，其马𫏋𫏋。其马𫏋𫏋，其音昭昭。载色载笑，匪怒伊教。","思乐泮水，薄采其茆。鲁侯戾止，在泮饮酒。既饮旨酒，永锡难老。顺彼长道，屈此群丑。","穆穆鲁侯，敬明其德。敬慎威仪，维民之则。允文允武，昭假烈祖。靡有不孝，自求伊祜。","明明鲁侯，克明其德。既作泮宫，淮夷攸服。矫矫虎臣，在泮献馘。淑问如皋陶，在泮献囚。","济济多士，克广德心。桓桓于征，狄彼东南。烝烝皇皇，不吴不扬。不告于讻，在泮献功。","角弓其觩。束矢其搜。戎车孔博。徒御无斁。既克淮夷，孔淑不逆。式固尔犹，淮夷卒获。","翩彼飞鸮，集于泮林。食我桑黮，怀我好音。憬彼淮夷，来献其琛。元龟象齿，大赂南金。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-298","tags":[]},{"id":"poem-3f71348a9ff07f7adc421301","title":"浣溪沙·花样风流柳样娇","author":"向子𬤇","dynasty":"宋","verses":["花样风流柳样娇。","雪中微步过溪桥。","心期春色到梅梢。","折得一枝归绿鬓，冰容玉艳不相饶。","索人同去醉金蕉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-797","tags":[]},{"id":"poem-3f73e6aedd483443b104f798","title":"经邹鲁祭孔子而叹之","author":"明皇帝","dynasty":"唐","verses":["夫子何为者？栖栖一代中。","地犹鄹氏邑，宅即鲁王宫。","叹凤嗟身否，伤麟怨道穷。","今看两楹奠，当与梦时同。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a1824eb8-4e2e-4d53-9a33-e1dcfe7d1c73","tags":["唐诗三百首","伤怀","写人","五言律诗"]},{"id":"poem-3f76e218d295e47a4b96c7bb","title":"秦楼月・忆秦娥·楼阴缺","author":"范成大","dynasty":"宋","verses":["楼阴缺。","阑干影卧东厢月。","东厢月。","一天风露，杏花如雪。","隔烟催漏金虬咽。","罗帏暗淡灯花结。","灯花结。","片时春梦，江南天阔。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-275","tags":["宋词三百首"]},{"id":"poem-3f855ec959b1e9d5f0cc4ac9","title":"北归将自英韶趋江表因游清远峡碧落洞谒六祖于曹溪望韶石渡庾岭皆峤南绝景也适江西道梗遵海而归此志不遂赋五绝见意 碧落洞","author":"李纲","dynasty":"宋","verses":["碧落嵌空群玉峰，烟霞深锁翠微重。","乳羊不作黄羊色，放筯能回冰雪容。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b1aeb448-d1d5-409d-acac-17891ddc264f","tags":[]},{"id":"poem-3f8644b043542f51caa9cb0f","title":"寿定叟弟  其一","author":"张栻","dynasty":"宋","verses":["今年黄菊开花早，手撷芳新寿一杯。","不用南阳三十斛，家山根蒂好栽培。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2e092146-44af-4cb4-865f-1f5362750832","tags":[]},{"id":"poem-3f8809461770de3fbe2e67c6","title":"句  其一","author":"陈俊卿","dynasty":"宋","verses":["吾方蹈孔孟，未暇师粲可。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1281b5aa-3787-4e7c-924b-98619897b8d2","tags":[]},{"id":"poem-3f883707e6326da88d4b6c67","title":"感藂草初生","author":"佚名","dynasty":"唐","verses":["覊客绝知闻，急难阻投杖。","泪与泉俱流，愁将草齐长。","缧绁淹岁年，归期唯梦想。","春色纵芳菲，片心终郁怏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cc2e8a04-c10f-4b19-a7ae-80620d30dd35","tags":[]},{"id":"poem-3fa22a39f8892cefd56f893a","title":"棋","author":"裴说","dynasty":"唐","verses":["十九条平路，言平又崄巇。","人心无算处，国手有输时。","势逈流星远，声干下雹迟。","临轩才一局，寒日又西垂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ae3e162f-6d07-4f90-ab29-9751c747d535","tags":[]},{"id":"poem-3fa3b3df92593fb531edfb42","title":"南歌子·柳色遮楼暗","author":"张泌","dynasty":"五代","verses":["柳色遮楼暗，桐花落砌香。","画堂开处远风凉，高卷水晶帘额，衬斜阳。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-47","tags":[]},{"id":"poem-3fa590b159b30f71fa5c06b3","title":"送客归新罗","author":"项斯","dynasty":"唐","verses":["君家沧海外，一别见何因。","风土虽知教，程途自致贫。","浸天波色晚，横笛鸟行春。","明发千樯下，应无更远人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-902a9264-d23b-412d-83a9-704718ac5bf5","tags":[]},{"id":"poem-3fa878d57cfa44b92b62c79a","title":"醉中看花因思去岁之任","author":"薛逢","dynasty":"唐","verses":["去岁乘轺出上京，军机旦暮促前程。","狂花野草途中恨，春月秋风劒外情。","愁见瘴烟遮路色，厌闻溪水下滩声。","不辞醉伴诸年少，羞对红妆白发生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e9d762c8-8e3d-48b1-ace5-4181634c2be3","tags":[]},{"id":"poem-3fa8d935cd2d29bd46ec98f0","title":"留题兴唐寺","author":"赵嘏","dynasty":"唐","verses":["满水楼台满寺山，七年今日共跻攀。","月高对菊问行客，去折芳枝早晚还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0376ad8f-cf2c-4088-93e3-482c8395e20e","tags":[]},{"id":"poem-3faf1099ede0f3a2a967e9ad","title":"日东病僧","author":"项斯","dynasty":"唐","verses":["云水绝归路，来时风送船。","不言身后事，犹坐病中禅。","深壁藏灯影，空窗出艾烟。","已无乡土信，起塔寺门前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bf4d1d67-24f7-4e25-8672-5bb1ad607810","tags":[]},{"id":"poem-3fb5c98129d160e067cac77f","title":"咏鹦鹉","author":"裴说","dynasty":"唐","verses":["常贵西山鸟，衔恩在玉堂。","语传明主意，衣拂美人香。","缓步寻珠网，高飞上画梁。","长安频道乐，何日从君王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-97582184-21c7-4f82-9f49-a80c8e30d0df","tags":[]},{"id":"poem-3fb5e9b7724aeb9e86a5e645","title":"菩萨蛮·如今却忆江南乐","author":"韦庄","dynasty":"五代","verses":["如今却忆江南乐，当时年少春衫薄。","骑马倚斜桥，满楼红袖招。","翠屏金屈曲，醉入花丛宿。","此度见花枝，白头誓不归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-35","tags":[]},{"id":"poem-3fc4af8aebf878e68f18322b","title":"卜算子·漠漠雨其蒙","author":"吴泳","dynasty":"宋","verses":["漠漠雨其蒙，湛湛江之永。","冻压溪桥并见花，安得杯中影。","明水未登彝，饰玉先浮鼎。","寄语清居山上翁，驿使催归近。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-594","tags":[]},{"id":"poem-3fdffb1c44209352b57fe108","title":"将就十章更献三首词虽愈拙诚即可矜或歌执事之风猷或导鄙人之情志愿宽捷给稍赐披寻  其三","author":"李昉","dynasty":"宋","verses":["野性从来只澹如，奉身求足不求余。","清风明月三间屋，赤轴黄签一架书。","午睡爱茶鱼眼细，春餐费笋锦皮疏。","比惭多病仍多告，犹拟分司洛下居。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e5b825c3-9006-4227-8886-8e1921798582","tags":[]},{"id":"poem-3fe179ef3829acbe92cf7c7b","title":"再入道场纪事应制","author":"沈佺期","dynasty":"唐","verses":["南方归去再生天，内殿今年异昔年。","见辟乾坤新定位，看题日月更高悬。","行随香辇登仙路，坐近炉烟讲法筵。","自喜恩深陪侍从，两朝长在圣人前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7875082b-2898-40df-bfab-681426ed3a03","tags":[]},{"id":"poem-3ff5a96a9c78051b512246d7","title":"兰陵王·卷朱箔","author":"张元干","dynasty":"宋","verses":["卷朱箔。","朝雨轻阴乍阁。","阑干外，烟柳弄晴，芳草侵阶映红药。","东风妒花恶。","吹落。","梢头嫩萼。","屏山掩，沈水倦熏，中酒心情怕杯勺。","寻思旧京洛。","正年少疏狂，歌笑迷著。","障泥油壁催梳掠。","曾驰道同载，上林携手，灯夜初过早共约。","又争信漂泊。","寂寞。","念行乐。","甚粉淡衣襟，音断弦索。","琼枝璧月春如昨。","怅别后华表，那回双鹤。","相思除是，向醉里、暂忘却。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-114","tags":["宋词三百首"]},{"id":"poem-3ff737698229c4e95df0c6cf","title":"意难忘·仙子奇容","author":"高观国","dynasty":"宋","verses":["仙子奇容。","是名花第一，美占春风。","烟香笼浅翠，露靓浥芳红。","怜舞燕，惜惊鸿。","想独步吴宫。","料认得、娇云媚雨，来自巫峰。","风流正与欢浓。","羡高楼并倚，曲影阑东。","烛摇留醉枕，尘坠恋歌钟。","三弄笛，五花骢。","莫行乐匆匆。","但看取、天长地久，笑语相逢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-416","tags":[]},{"id":"poem-400177f1709cdebf4c8f23e1","title":"贺新郎·篆缕销金鼎","author":"李玉","dynasty":"宋","verses":["篆缕销金鼎。","醉沈沈、庭阴转午，画堂人静。","芳草王孙知何处，惟有杨花糁径。","渐玉枕、腾腾春醒。","帘外残红春已透，镇无聊、酒厌厌病。","云鬓乱，未整。","江南旧事休重省。","遍天涯、寻消问息，断鸿难倩。","月满西楼凭栏久，依旧归期未定。","又只恐、瓶沈金井。","嘶骑不来银烛暗，枉教人、立尽梧桐影。","谁伴我，对鸾镜。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-111","tags":["宋词三百首"]},{"id":"poem-400be0ec033bf835d0a784f8","title":"经仙人渚即沈山下古人沈义白日升仙处","author":"皎然","dynasty":"唐","verses":["日月人间短，何时此得仙。","古山春已尽，遗渚事空传。","不见腾云驾，徒临洗药泉。","如今成逝水，翻使恨流年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-00148577-1689-4ef2-ae7f-9bc484345c53","tags":[]},{"id":"poem-401502f1afef9c826dc247f2","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["你莫打渠，苦必苦，厮打你每早先输。","你腰我腰，没钱又无米。","(合)担儿把去，今夜两个在那里睡！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2481","tags":[]},{"id":"poem-4023bfb77bd6ff85abcabf1e","title":"郊庙歌辞 享太庙乐章 迎神","author":"不详","dynasty":"唐","verses":["七庙观德，百灵攸仰。","俗荷财成，物资含养。","道光执契，化笼提象。","肃肃雍雍，神其来飨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-70baddd6-6128-41d4-bc8c-a409dd9a9939","tags":[]},{"id":"poem-4025441a60968a0e94c5d7d8","title":"清平乐·何处游女","author":"韦庄","dynasty":"五代","verses":["何处游女，蜀国多云雨。","云解有情花解语，窣地绣罗金缕。","妆成不整金钿，含羞待月秋千。","住在绿槐阴里，门临春水桥边。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-47","tags":[]},{"id":"poem-402e7e56860dff8fd3e514bd","title":"菩萨蛮·客中愁损催寒夕","author":"纳兰性德","dynasty":"清","verses":["客中愁损催寒夕，夕寒催损愁中客。","门掩月黄昏，昏黄月掩门。","翠衾孤拥醉，醉拥孤衾翠。","醒莫更多情，情多更莫醒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-219","tags":[]},{"id":"poem-4038859ce369f4c7fece2bb1","title":"九子峰","author":"陈岩","dynasty":"宋","verses":["小大扶携作伴行，欢然恋恋意相倾。","信知万古山头石，还有人间母子情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-09d902cf-0869-4190-aae0-c3aac28ab275","tags":[]},{"id":"poem-403a0de2a7f86b20cb7fa6a8","title":"一撮棹","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["宽心等，何须苦牵萦？(外)把音书写，但频频寄邮亭。","(贴)老姥姥，爹年老，我去呵，伊家须好看承。","(合)程途里，只愿保安宁。","死别全无准，生离又难定。","今去也，何日到京城？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5254","tags":[]},{"id":"poem-4042b9176f75c43ac3740060","title":"郊庙歌辞 德明兴圣庙乐章 登歌奠币","author":"李舒","dynasty":"唐","verses":["四时有典，百事来祭。","尊祖奉宗，严禋大帝。","礼先苍璧，奠币黝制。","于斯万年，熙成帝系。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ea9c019e-a6fb-4620-847b-130634b1b349","tags":[]},{"id":"poem-4047adad2393f813e55dc504","title":"虹县旧题二首  其二","author":"米芾","dynasty":"宋","verses":["碧榆绿柳旧游中，华发苍颜未退翁。","天使残年司笔砚，圣知小学是家风。","长安又到人徒老，吾道何时定复东。","题柱扁舟真老矣，竟无事业奏肤公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b19879f9-2434-4711-a70c-4baf3de2ccf9","tags":[]},{"id":"poem-4047b84990aff13304d01496","title":"点绛唇·浊酒黄花","author":"黄庭坚","dynasty":"宋","verses":["浊酒黄花，画檐十日无秋燕。","梦中相见。","起作南柯观。","镜里朱颜，又减年时半。","江山远。","登高人健。","应问西来雁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-716","tags":[]},{"id":"poem-404c7a79fa6d466c28ccbfd7","title":"送春","author":"王令","dynasty":"宋","verses":["三月残花落更开，小檐日日燕飞来。","子规夜半犹啼血，不信东风唤不回。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送春","tags":[]},{"id":"poem-404ebcc1b8b9918ce7eac70f","title":"诸暨五泄山","author":"周镛","dynasty":"唐","verses":["路入苍烟九过溪，九穿岩曲到招提。","天分五溜寒倾北，地秀诸峰翠插西。","凿径破崖来木杪，驾泉鸣竹落榱题。","当年老默无消息，犹有词堂一杖藜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2ba5b680-8c05-46fa-8ca3-80cff02ee98a","tags":[]},{"id":"poem-4054570438c05540e8b2a005","title":"灵岩","author":"姚辟","dynasty":"宋","verses":["泉石平生性所耽，谢公延我到东南。","红莲幕下烦佳客，文脊山中访旧岩。","剪竹扫花寻鸟道，扪萝随衲问龙潭。","图经未尽幽潜事，待向仙家起玉函。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-26cca302-8fd8-4fbe-93d4-be82a0769808","tags":[]},{"id":"poem-405900f7f65a2f25ea74d234","title":"望江梅·闲梦远","author":"李煜","dynasty":"五代","verses":["闲梦远，南国正芳春。","船上管弦江面绿，满城飞絮滚轻尘。","忙杀看花人。","闲梦远，南国正清秋。","千里江山寒色暮，芦花深处泊孤舟。","笛在月明楼。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-20","tags":[]},{"id":"poem-405b001f76c23825790fdf86","title":"玉树后庭花・后庭花·宝床香重春眠觉","author":"张先","dynasty":"宋","verses":["宝床香重春眠觉。","魫窗难晓。","新声丽色千人，歌后庭清妙。","青骢一骑来飞鸟。","靓妆难好。","至今落日寒蟾，照台城秋草。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-387","tags":[]},{"id":"poem-405ffb6fca6ef8310dd03b59","title":"滴滴金·阴阴湿雾霜无汁","author":"王质","dynasty":"宋","verses":["阴阴湿雾霜无汁。","江气逼、树声滴。","荒林只见夕阳入。","谁唤晚烟集。","渔翁犹把钓竿执。","蓑共笠、时时葺。","风刚浪猛早收拾。","天外暮云黑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-322","tags":[]},{"id":"poem-4068ecdcd64ababbd386cf54","title":"百舌鸟二首 二","author":"无则","dynasty":"唐","verses":["长截隣鸡叫五更，数般名字百般声。","饶伊摇舌先知晓，也待青天明即鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-46fa6fc6-61d8-478a-ae84-429cf9a4871a","tags":[]},{"id":"poem-406be0f078566489cf262f7f","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你每真个见鬼，这松柏孤坟在何处？恰才小鬼是我妆做的。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5149","tags":[]},{"id":"poem-4075da9c5ec7a1d73960cd84","title":"同敬八卢五泛河间清河","author":"高适","dynasty":"唐","verses":["清川在城下，沿泛多所宜。","同济惬数公，玩物欣良时。","飘飖波上兴，燕婉舟中词。","昔陟乃平原，今来忽涟漪。","东流达沧海，西流延滹池。","云树共晦明，井邑相逶迤。","稍随归月帆，若与沙鸥期。","渔父更留我，前潭水未滋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e7fe9e63-321b-4afd-8a47-3dc37dbf7ba6","tags":[]},{"id":"poem-4076a45ec0d92e46a67023b6","title":"同前换头","author":"萧德祥《小孙屠》","dynasty":"元","verses":["幸逢你，谁知三见鬼，一齐都擒住。","千般受险危，幸得天天周济。","两人怎插翅？口遍身如何分理？是共非，到龙图阶下听取台旨。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8681","tags":[]},{"id":"poem-407942436ad4f1032d24183c","title":"过邠州留题","author":"窦仪","dynasty":"宋","verses":["多少樊笼不敢开，强拘物性要相倍。","何时得似邠州守，德政临民鹤自来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-03826275-4c34-46c6-876d-67728055d828","tags":[]},{"id":"poem-408a5cb234dc35fb91192850","title":"扈驾马兰峪赐观温泉恭纪十韵","author":"纳兰性德","dynasty":"清","verses":["御天来凤辇，浴日启龙池。","野迥纡皇览，春浓值圣时。","落花萦彩仗，初柳拂朱旗。","行漏三辰拥，停銮万象随。","瑞征泉是醴，喜溢沼生芝。","特许观灵液，相将涉禁墀。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-221","tags":[]},{"id":"poem-408cd045f006eb1de5eacad6","title":"洞仙歌·温江异果","author":"晁补之","dynasty":"宋","verses":["温江异果，惟有泥山贵。","驿送江南数千里。","半含霜，轻噀雾，曾怯吴姬，亲赠我，绿桔黄柑怎比。","双亲云水外，游子空怀，惆怅无人可归遗。","报周郎、须念我，物少情多，春酒醉，独胜甜桃醋李。","况灯火楼台近元宵，似不减年时，袖中香味。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-290","tags":[]},{"id":"poem-4096af900d9eb4d41a2e4cbe","title":"题泗州刘中丞郡中新楼。","author":"张祜","dynasty":"唐","verses":["一槛构庭上，临川望益崇。","朗怀披夏日，高啸得清风。","紫府须黄霸，青山属谢公。","夜声闻动草，春意觉抽丛。","野迥云初白，天寒树间红。","月华深委素，淮色逈流空。","暮雨佳人到，良辰乐事同。","更怜初渡水，先咏子来工。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c98078a0-ace6-4b84-aaf9-d25914d4accd","tags":[]},{"id":"poem-4096fd69b6d09b516c9e745b","title":"登翅头山题俨公石壁","author":"包融","dynasty":"唐","verses":["晨登翅头山，山曛黄雾起。","却瞻迷向背，直下失城市。","暾日衔东郊，朝光生邑里。","扫除诸烟氛，照出众楼雉。","青为洞庭山，白是太湖水。","苍茫远郊树，倏忽不相似。","万象以区别，森然共盈几。","坐令开心胸，渐觉落尘滓。","北岩千余仞，结庐谁家子。","愿陪中峰游，朝暮白云里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-64e5a06a-f81d-49c7-9a5d-b6c4fdbbcd91","tags":["太湖","洞庭湖"]},{"id":"poem-4097afe352d5f334e2dfb346","title":"送暕上人游春","author":"李端","dynasty":"唐","verses":["独将支遁去，欲往戴颙家。","晴野人临水，春山树发花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d7ca2c1c-1daa-495e-9796-f1e31472bdb2","tags":[]},{"id":"poem-40a28134827fc846a107a7d4","title":"喜杨舍人入翰林","author":"卢肇","dynasty":"唐","verses":["御笔亲批翰长衔，夜开金殿送瑶缄。","平明玉案临宣室，已见龙光出傅岩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-41de33cc-8047-40b7-8c95-11b2668051e1","tags":[]},{"id":"poem-40a47d31eed34907fb291eb6","title":"渔父词・渔父·谁云渔父是愚翁","author":"赵构","dynasty":"宋","verses":["谁云渔父是愚翁。","一叶浮家万虑空。","轻破浪，细迎风。","睡起篷窗日正中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-223","tags":[]},{"id":"poem-40a929b36e17417602f8fc77","title":"至日荷李常侍过郊居","author":"熊孺登","dynasty":"唐","verses":["贱子守柴荆，谁人记姓名。","风云千骑降，草木一阳生。","礼异江河动，欢殊里巷惊。","称觞容侍坐，看竹许同行。","遇觉沧溟浅，恩疑太岳轻。","尽搜天地物，无谕此时情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5a854bf0-ae31-49a9-9dbc-caf2a34eb461","tags":[]},{"id":"poem-40b366c0721c9847bcafaaf7","title":"拜丰陵","author":"张籍","dynasty":"唐","verses":["岁朝园寝遣公卿，学省班中亦摄行。","身逐陵官齐再拜，手持木铎叩三声。","寒更报点来山殿，晓炬分行照栢城。","却下龙门看渐远，金峰高处日微明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3fee945e-5d15-48c3-9ca1-4115f9ee27cd","tags":[]},{"id":"poem-40b5b23289881a06149fcc9a","title":"答僧问好晴好雨颂（题拟）","author":"道怤","dynasty":"唐","verses":["好晴好雨奇行持，若随语会落今时。","谈玄只要尘中妙，得妙还同不惜伊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-47312476-0004-404e-b88d-522861c67dad","tags":[]},{"id":"poem-40b98128636311cc9a3ad5c0","title":"玉楼春·东风又作无情计","author":"晏几道","dynasty":"宋","verses":["东风又作无情计。","艳粉娇红吹满地。","碧楼帘影不遮愁，还似去年今日意。","谁知错管春残事。","到处登临曾费泪。","此时金盏直须深，看尽落花能几醉。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-28","tags":["宋词三百首"]},{"id":"poem-40c0fa6b322febc35f8fae4a","title":"同李洗马入余不溪经辛将军故城","author":"皎然","dynasty":"唐","verses":["惨惨寒城望，将军下世时。","高墉暮草遍，大树野风悲。","壁垒今惟在，勋庸近可思。","苍然古溪上，川逝共凄其。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6a081af9-da14-448e-90b1-7768a2b7ba88","tags":[]},{"id":"poem-40ccc7c3783aeb51417069c0","title":"春日留别","author":"孙逖","dynasty":"唐","verses":["春路逶迤花柳前，孤舟晚泊就人烟。","东山白云不可见，西陵江月夜娟娟。","春江夜尽潮声度，征帆遥从此中去。","越国山川看渐无，可怜愁思江南树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0565e377-860d-4848-abfe-ff6420c9409f","tags":[]},{"id":"poem-40cde59c32cb2e47a4619c43","title":"夜听捣衣诗","author":"杨泰师","dynasty":"唐","verses":["霜天月照夜河明，客子思归别有情。","厌坐长宵愁欲死，忽闻邻女捣衣声。","声来继续因风至，夜久星低无暂止。","自从别国不相闻，今在他乡听相似。","不知彩杵重将轻，不悉青砧（一作「碪」）平不平。","遥怜体弱多香汗，预识更深劳玉腕。","为当欲救客衣单，为复先愁闺阁寒。","虽忘容仪难可问，不知遥意怨无端。","寄异土兮无新识，想同心兮长叹傦。","此时独自闺中闻，此夜谁知明眸缩。","忆忆兮心已悬，重闻（一作「闭」）兮不可穿。","既将因梦寻声去，只为愁多不得眠。","（诗见金毓黻撰集《渤海国志长编》卷十八引《经国集》十三。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-05ecf53b-2c7f-46ec-8238-4d9a4a0a1590","tags":[]},{"id":"poem-40cf12da131f8b1847d9b0dc","title":"答文成","author":"张𬸦","dynasty":"唐","verses":["素手曾经捉，纤腰又被将。","即今输口子，余事可平章。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5544e25a-6fdd-4190-9e3b-e8a9b1f553ca","tags":[]},{"id":"poem-40d8be6f87db8b2e9433347c","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)只见数点寒鸦，投林乱鸣，晚烟宿雾冥冥。","迢迢古岸水澄澄，野渡无人舟自横。","不忍听，不美听，听得孤鸿天外两三声。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2972","tags":[]},{"id":"poem-40e6722bf819a9d051141cfd","title":"奉酬睢阳路太守见赠之作","author":"高适","dynasty":"唐","verses":["盛才膺命代，高价动良时。","帝简登藩翰，人和发咏思。","神仙去华省，鹓鹭忆丹墀。","清净能无事，优游即赋诗。","江山纷想像，云物共萎蕤。","逸气刘公干，玄言向子期。","多慙汲引速，翻愧激昂迟。","相马知何限，登龙反自疑。","风尘吏道迫，行迈旅心悲。","拙疾徒为尔，穷愁欲问谁。","秋庭一片叶，朝镜数茎丝。","州县甘无取，丘园悔莫追。","琼瑶生箧笥，光景借茅茨。","他日青霄里，犹应访所知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-8687726e-b4b8-48f3-be61-f73ccf881e92","tags":[]},{"id":"poem-40ed73e3d2662a7bbedf7d9b","title":"答白杭州郡楼登望画图见寄","author":"张籍","dynasty":"唐","verses":["画得江城登望处，寄来今日到长安。","乍惊物色从诗出，更想工人下手难。","将展书堂偏觉好，每来朝客尽求看。","见君向此闲吟意，肯恨当时作外官。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-28527ad0-4b09-4eca-8a74-79a1ab1aa755","tags":[]},{"id":"poem-40ee7584ec98171fe3c2f2e0","title":"闲居作五首 其一","author":"张祜","dynasty":"唐","verses":["十年狂是酒，一世癖缘诗。","剩物心长厌，闲书性理不违。","补窠新鷰子，争食乳鸦儿。","幸尔隣家竹，春来又许移。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f8af2220-e975-410e-ba37-eaa3512099c5","tags":[]},{"id":"poem-40f006d91a7be7869cfadd98","title":"新月","author":"卢仝","dynasty":"唐","verses":["仙宫云箔卷，露出玉帘钩。","清光无所赠，相忆凤皇楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-848eba6c-b222-4d42-92c5-c40f4d9fc35d","tags":[]},{"id":"poem-40f1da33dd9cf58462daafc2","title":"新水令","author":"施惠《幽闺记》","dynasty":"元","verses":["(外怒科，外)九重天听望垂慈，主君贤谏臣须直。","事当言敢自欺？既为官要尽臣职。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2861","tags":[]},{"id":"poem-40f335382b1042f39d3fd402","title":"雨后出城马上作","author":"林之奇","dynasty":"宋","verses":["既雨天气佳，微云淡如扫。","欲寻烟际钟，骑马河边草。","紫椹饱黄鹂，人家夏蚕老。","田妇踏缫车，隔篱语音好。","嗟我一何愚，读书浪枯槁。","不及此中人，终年客长道。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4aba4cad-c5b8-4930-905f-7ff10c781e4e","tags":[]},{"id":"poem-40f97fe241a9c8e12400e775","title":"虞美人·风前玉树玱金韵","author":"谢逸","dynasty":"宋","verses":["风前玉树玱金韵。","碧落佳期近。","疏云影里鹊桥低。","檐外一弯新月、印修眉。","星河渐晓铜壶噎。","又是经年别。","此情莫与玉人知。","引起旧家离恨、泪珠垂。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-614","tags":[]},{"id":"poem-4101c3aea8979fdab3518393","title":"绕地游","author":"刘唐卿《白兔记》","dynasty":"元","verses":["朱扉画戟，画堂中万千丰丽。","幸吾父品登高位，文武中尽称为最。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8972","tags":[]},{"id":"poem-41024aa9a2ad272893523891","title":"武陵桃源送人","author":"包融","dynasty":"唐","verses":["武陵川径入幽遐，中有鸡犬秦人家。","先时见者为谁耶，源水今流桃复花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a01291fb-dbf6-478b-a177-2e8bbb9c5584","tags":["送别"]},{"id":"poem-4102b569a1a45c7f9265720d","title":"和裴仆射看樱桃花","author":"张籍","dynasty":"唐","verses":["昨日南园新雨后，樱桃花发旧枝柯。","天明不待人同看，遶树重重履迹多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-badab31e-682c-4658-9a2e-cb2b13e317f0","tags":[]},{"id":"poem-410c973ffb9bdcea25489635","title":"忘归亭","author":"陈岩","dynasty":"宋","verses":["两袖飘飘恍欲仙，半醒半醉酒明船。","太虚一室都无碍，皎月凉风石上眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-521fec2b-c142-4e26-ae70-91b597d55fb2","tags":[]},{"id":"poem-4118eb8b344b9a59be0685f0","title":"送舍弟孺复往庐山","author":"熊孺登","dynasty":"唐","verses":["能骑竹马辨西东，未省烟花暂不同。","第一早归春欲尽，庐山好看过湖风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9522d29d-f489-4b7f-ba58-d741b60a2f12","tags":["庐山"]},{"id":"poem-4123099faeb7a26172a73f25","title":"蝶恋花·推上百花如锦绣","author":"向子𬤇","dynasty":"宋","verses":["推上百花如锦绣。","水满池塘，更作溅溅溜。","断送风光惟有酒。","苦吟不怕因诗瘦。","寻壑经丘长是久。","晚晚归来，稚子柴门候。","万事付之醒梦后。","眉头不为闲愁皱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-98","tags":[]},{"id":"poem-4128f0d8e5cb5a70c2550249","title":"赠皇甫侍御赴都八首 二","author":"元希声","dynasty":"唐","verses":["猗嗟众珍，以况君子。","公侯之胄，必复其始。","利器长材，温仪峻峙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-56a904d9-d977-44b0-be67-1cce4b11e5bc","tags":[]},{"id":"poem-41332b72c2fec785d1b77432","title":"有客","author":"佚名","dynasty":"先秦","verses":["有客有客，亦白其马。有萋有且，敦琢其旅。有客宿宿，有客信信。","言授之絷，以絷其马。薄言追之，左右绥之。既有淫威，降福孔夷。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-283","tags":[]},{"id":"poem-4136c4893ac546910db27745","title":"谒金门·云外月","author":"韩淲","dynasty":"宋","verses":["云外月。","画出一痕清绝。","梅已飘零桃未发。","带湖烟水阔。","汀渚尚留微雪。","不恨酒融歌歇。","老我多情胶漫结。","半醒空自说。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-467","tags":[]},{"id":"poem-413753586385a827a153ca9a","title":"望吾乡","author":"施惠《幽闺记》","dynasty":"元","verses":["(众)仰圣瞻天恩，光照绮筵。","花枝掩映春风面，女貌郎才真堪羡。","天遣为姻眷，双飞鸟，并蒂莲，今朝得遂平生愿。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3121","tags":[]},{"id":"poem-4142453dc85ca03f01fc7789","title":"移兰","author":"释居简","dynasty":"宋","verses":["莸劣薰优只自强，寄林亦足称孤芳。","故应纫佩成春服，不为无人閟国香。","移傍瘦筠同雨露，怕随行苇践牛羊。","客非九畹同心事，莫反离骚吊碧湘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-86df2e49-a1d1-4cd2-b70d-476edf087ba0","tags":[]},{"id":"poem-41467c79b3951207002591fa","title":"重九陪详刑护漕东西楼之集","author":"张栻","dynasty":"宋","verses":["猎猎西风满角巾，登临秋思与云平。","山围四野高低碧，江遶东城今古清。","莫恨寒花未堪摘，且忻樽酒得同倾。","政须客里频回首，细话家山此日情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-570f6f5e-01a0-4bb5-8404-2775e7f72270","tags":[]},{"id":"poem-4147f02c046f06eb36716603","title":"心游楼即事","author":"刘翼","dynasty":"宋","verses":["禅坐宁离此，意行何所如。","稻粱诗七月，果木赋闲居。","活水尝新茗，颠风落旧书。","无才甘用拙，不是隠樵渔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f2432767-0e3c-4249-b648-0af6ed872751","tags":[]},{"id":"poem-4152e1ce9db65f4dc95da13a","title":"菩萨蛮·鸳鸯枕上云堆绿","author":"蔡伸","dynasty":"宋","verses":["鸳鸯枕上云堆绿。","兰膏微润知新沐。","开帐对华灯。","见郎双眼明。","锦衾香馥郁。","槛竹敲寒玉。","何物最无情。","晓鸡咿喔声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-976","tags":[]},{"id":"poem-415396a72f4bae98eb91e3bd","title":"元日望含元殿御扇开合","author":"章八元","dynasty":"唐","verses":["万国来朝岁，千年觐圣君。","辇迎仙杖出，扇匝御香焚。","俯对朝容近，先知曙色分。","冕旒开处见，钟磬合时闻。","影动承朝日，花攒似庆云。","蒲葵那可比，徒用隔炎氛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1a6a438f-ee84-40e8-8e66-56ccc4ace6df","tags":[]},{"id":"poem-415dc48e5079a299c4452c2e","title":"四望亭","author":"朱景玄","dynasty":"唐","verses":["高亭群峰首，四面俯晴川。","每见晨光晓，阶前万井烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-efd5b98e-0945-4545-8249-c0e0e10a89e4","tags":[]},{"id":"poem-4164532be59e6d5b878cbaef","title":"赠张云容舞","author":"杨贵妃","dynasty":"唐","verses":["罗袖动香香不已，红蕖褭褭秋烟里。","轻云岭上乍摇风，嫩柳池边初拂水。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-225f48d3-f1c0-4917-bbee-32aa163d5077","tags":[]},{"id":"poem-4170bb48adc59b7b578d9b0d","title":"眼儿媚·中元夜有感","author":"纳兰性德","dynasty":"清","verses":["手写香台金字经，惟愿结来生。","莲花漏转，杨枝露滴，想鉴微诚。","欲知奉倩神伤极，凭诉与秋擎。","西风不管，一池萍水，几点荷灯。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-147","tags":[]},{"id":"poem-41763c30298f46d5a2e4628a","title":"相和歌辞 江南曲","author":"李益","dynasty":"唐","verses":["嫁得瞿塘贾，朝朝误妾期。","早知潮有信，嫁与弄潮儿。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bb111748-d8f1-4a5e-b618-b70272a7a642","tags":["唐诗三百首","闺怨","乐府"]},{"id":"poem-4177ae4a3a7303d56c615922","title":"横吹曲辞 陇头水","author":"鲍溶","dynasty":"唐","verses":["陇头水，千古不堪闻。","生归苏属国，死别李将军。","细响风凋草，清哀雁落云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5e38232f-f517-43be-8d90-4945ae90b92b","tags":[]},{"id":"poem-4183d5b089aa6611a59b42a8","title":"句 二","author":"杨徽之","dynasty":"唐","verses":["春归万年树，月满九重城（《元夜》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0fd2861d-9448-4bf5-a25d-7cf3b303c3f4","tags":[]},{"id":"poem-4185b18829f7afbde91f8658","title":"金山寺空上人院","author":"张乔","dynasty":"唐","verses":["已老金山顶，无心上石桥。","讲移三楚遍，梵译五天遥。","板阁禅秋月，铜瓶汲夜潮。","自慙昏醉客，来坐亦通宵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d1b869eb-0d87-4dbc-be12-8c3611e6891c","tags":[]},{"id":"poem-4188f75b7b1db68691bf085f","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十一","author":"易静","dynasty":"唐","verses":["他军走（京本作「是」），虚实（辛本、川本、京本作「的」）好参陈。","神克日辰天马并，传扬定去必无人，此兆决然真。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-01ba13c4-f92b-4e21-aaa8-95774338efb4","tags":[]},{"id":"poem-4194100fc863933a49b4a3ee","title":"塞下曲 三","author":"李益","dynasty":"唐","verses":["黄河东流流九折，沙场埋恨何时绝。","蔡琰没去造胡笳，苏武归来持汉节。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b7c28260-45f1-466e-b5fb-901240b9bee5","tags":["黄河"]},{"id":"poem-4198d882eec1100a893483ea","title":"关下","author":"崔道融","dynasty":"唐","verses":["百二山河壮帝畿，关门何事更开迟。","应从漏却田文后，每度闻鸡不免疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3d4e4652-222a-4e7c-aca6-2f7dcd113df6","tags":[]},{"id":"poem-419bdf06fe7a3f834c8d6cf1","title":"黄台瓜辞","author":"章怀太子","dynasty":"唐","verses":["种瓜黄台下，瓜熟子离离。","一摘使瓜好，再摘使瓜稀。","三摘犹自可，摘绝抱蔓归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ef8c04bf-a29b-4537-bebb-256c6604126c","tags":[]},{"id":"poem-419caf85f1efe3800cc285b3","title":"郊庙歌辞 祭汾阴乐章 太簇角","author":"卢从愿","dynasty":"唐","verses":["坤元载物，阳乐发生。","播殖资始，品汇咸亨。","列俎棋布，方坛砥平。","神歆禋祀，后德惟明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b82134e2-ef7b-41be-be33-96703019de32","tags":[]},{"id":"poem-41a1aa97828a2b228ae99c16","title":"金谷园","author":"曹松","dynasty":"唐","verses":["当年歌舞时，不说草离离。","今日歌舞尽，满园秋露垂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-507eda7a-f94e-41cc-aefd-e6cbdec7c5a8","tags":[]},{"id":"poem-41a22b2c2bcce8b645779dfb","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、旦)区区，山行路宿，粥食无觅处。","有盘缠肯相推阻？(众)穷酸饿儒，模样须寻俗。","随行所有，疾忙分付。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2957","tags":[]},{"id":"poem-41a23833607c753b12d320a8","title":"十诗谢廖计使  其四","author":"陈造","dynasty":"宋","verses":["偓佺地上仙，笙鹤不我遐。","楚骚欲命仆，古诗无名家。","晋当泽帝范，小却侈国华。","本末计中外，倚须拜亨嘉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8360f219-dc5c-4ca9-9822-2f25453318e0","tags":[]},{"id":"poem-41a8d43a8c229c98f6b112b2","title":"湖中","author":"赵崇鉘","dynasty":"宋","verses":["汀蒲猎猎起凉飔，碧藕香中独立时。","机事两忘吾丧我，扁舟吟过水仙祠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-83d15256-26c0-4618-afe8-103babdb96a6","tags":[]},{"id":"poem-41c01612db52ed96a3787a23","title":"风名","author":"闾丘均","dynasty":"唐","verses":["玉阶王道泰，金门词藻多。","文雄自指引，美景相经过。","野气连空谷，春色满长河。","方从君子会，终宴且当歌。","（见影印本《新编纂图增类群书类要事林广记》卷七。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8d66bf97-bf62-4fb1-bf24-f219a9fb5232","tags":[]},{"id":"poem-41c8f4af5ad023a7cf98077e","title":"江行无题一百首 八十四","author":"钱珝","dynasty":"唐","verses":["数亩苍苔石，烟蒙鹤卵洲。","定因词客遇，名字始风流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b51b6f9a-b058-4c34-896e-09f1f4ba286a","tags":[]},{"id":"poem-41ca966de36be85d6d1721b6","title":"九章·惜往日","author":"屈原","dynasty":"先秦","verses":["惜往日之曾信兮，受命诏以昭时。","奉先功以照下兮，明法度之嫌疑。","国富强而法立兮，属贞臣而日竢。","秘密事之载心兮，虽过失犹弗治。","心纯庞而不泄兮，遭谗人而嫉之。","君含怒而待臣兮，不清澈其然否。","蔽晦君之聪明兮，虚惑误又以欺。","弗参验以考实兮，远迁臣而弗思。","信谗谀之浑浊兮，盛气志而过之。","何贞臣之无罪兮，被离谤而见尤。","惭光景之诚信兮，身幽隐而备之。","临沅湘之玄渊兮，遂自忍而沉流。","卒没身而绝名兮，惜壅君之不昭。","君无度而弗察兮，使芳草为薮幽。","焉舒情而抽信兮，恬死亡而不聊。","独障壅而弊隐兮，使贞臣为无由。","闻百里之为虏兮，伊尹烹于庖厨。","吕望屠于朝歌兮，宁戚歌而饭牛。","不逢汤武与桓缪兮，世孰云而知之。","吴信谗而弗味兮，子胥死而后忧。","介子忠而立枯兮，文君寤而追求。","封介山而为之禁兮，报大德之优游。","思久故之亲身兮，因缟素而哭之。","或忠信而死节兮，或𫍙谩而不疑。","弗省察而按实兮，听谗人之虚辞。","芳与泽其杂糅兮，孰申旦而别之？","何芳草之早殀兮，微霜降而下戒。","谅聪不明而蔽壅兮，使谗谀而日得。","自前世之嫉贤兮，谓蕙若其不可佩。","妒佳冶之芬芳兮，嫫母姣而自好。","虽有西施之美容兮，谗妒入以自代。","愿陈情以白行兮，得罪过之不意。","情冤见之日明兮，如列宿之错置。","乘骐骥而驰骋兮，无辔衔而自载。","乘泛泭以下流兮，无舟楫而自备。","背法度而心治兮，辟与此其无异。","宁溘死而流亡兮，恐祸殃之有再。","不毕辞而赴渊兮，惜壅君之不识。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-19","tags":[]},{"id":"poem-41cabbc10a4ddf2de89e7f2e","title":"为有","author":"李商隐","dynasty":"唐","verses":["为有云屏无限娇，凤城寒尽怕春宵。","无端嫁得金龟壻，辜负香衾事早朝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-974914ee-1fc0-4952-a863-820bad2e4065","tags":["唐诗三百首","七言绝句","怨情"]},{"id":"poem-41dd73b4268643b702a3f3ba","title":"九叹·惜贤","author":"刘向","dynasty":"汉","verses":["览屈氏之离骚兮，心哀哀而怫郁。","声嗷嗷以寂寥兮，顾仆夫之憔悴。","拨谄谀而匡邪兮，切淟涊之流俗。","荡渨涹之奸咎兮，夷蠢蠢之溷浊。","怀芬香而挟蕙兮，佩江蓠之婓婓。","握申椒与杜若兮，冠浮云之峨峨。","登长陵而四望兮，览芷圃之蠡蠡。","游兰皋与蕙林兮，睨玉石之㟥嵯。","扬精华以炫燿兮，芳郁渥而纯美。","结桂树之旖旎兮，纫荃蕙与辛夷。","芳若兹而不御兮，捐林薄而菀死。","驱子侨之奔走兮，申徒狄之赴渊。","若由夷之纯美兮，介子推之隐山。","晋申生之离殃兮，荆和氏之泣血。","吴申胥之抉眼兮，王子比干之横废。","欲卑身而下体兮，心隐恻而不置。","方圜殊而不合兮，钩绳用而异态。","欲俟时于须臾兮，日阴曀其将暮。","时迟迟其日进兮，年忽忽而日度。","妄周容而入世兮，内距闭而不开。","俟时风之清激兮，愈氛雾其如塺。","进雄鸠之耿耿兮，谗介介而蔽之。","默顺风以偃仰兮，尚由由而进之。","心懭悢以冤结兮，情舛错以曼忧。","搴薜荔于山野兮，采撚支于中洲。","望高丘而叹涕兮，悲吸吸而长怀。","孰契契而委栋兮，日晻晻而下颓。","叹曰：江湘油油长流汩兮，挑揄扬汰荡迅疾兮。","忧心展转愁怫郁兮，冤结未舒长隐忿兮，丁时逢殃可奈何兮，劳心悁悁涕滂沱兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-51","tags":[]},{"id":"poem-41e35c5220bb51d8b760d0e7","title":"杏园芳·严妆嫩脸花明","author":"尹鹗 六首","dynasty":"五代","verses":["严妆嫩脸花明，教人见了关情。","含羞举步越罗轻，称娉婷。","终朝咫尺窥香阁，迢遥似隔层城。","何时休遣梦相萦，入云屏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-30","tags":[]},{"id":"poem-41e681614464829794c0384c","title":"感讽五首 二","author":"李贺","dynasty":"唐","verses":["奇俊无少年，日车何躃躃。","我待纡双绶，遗我星星发。","都门贾生墓，青蝇久断绝。","寒食摇扬天，愤景长肃杀。","皇汉十二帝，唯帝称睿哲。","一夕信竖儿，文明永沦歇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4210ab0f-985d-4ca2-bc11-037cee0d3d73","tags":[]},{"id":"poem-41e9a1afcd614654ea02553a","title":"题晖师影堂","author":"张籍","dynasty":"唐","verses":["日早欲参禅，竟无相识缘。","道场今独到，惆怅影堂前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-afe54c56-6577-4031-9610-361371e02256","tags":[]},{"id":"poem-41ea582d048d742ff766eba6","title":"偈颂（幷序○序为南岳齐己撰） 五十五","author":"居遁","dynasty":"唐","verses":["若教求道似求名，世上无人道不成。","心静道场何曾到，世间尘路等闲行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-89a17ab7-c57e-4faa-9e99-df9969a75d43","tags":["衡山"]},{"id":"poem-41f524606261ccec11d7c5b4","title":"升平词十首 六","author":"薛能","dynasty":"唐","verses":["日日听歌谣，区中尽祝尧。","虫蝗初不害，夷狄近全销。","史笔惟书瑞，天台绝见妖。","因令匹夫志，转欲事清朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4c7df6d8-f7cc-4476-b568-7fec18cc4cb7","tags":[]},{"id":"poem-41faca0a7464b069a8a23b00","title":"秋日赴阙题潼关驿楼","author":"许浑","dynasty":"唐","verses":["红叶晚萧萧，长亭酒一瓢。","残云归太华，疎雨过中条。","树色随山迥，河声入海遥。","帝乡明日到，犹自梦渔樵。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-292c14cd-151f-4321-a94c-46fc86693eb3","tags":["唐诗三百首","写景","送别","五言律诗"]},{"id":"poem-42063a4d7c84380bead07d24","title":"经王处士原居","author":"张籍","dynasty":"唐","verses":["旧宅谁相近，唯僧近竹关。","庭闲云满井，窗晓雪通山。","来客半留宿，借书多寄还。","明时未中岁，莫便一生闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-bf94838a-f165-449a-9069-c9564727a8ae","tags":[]},{"id":"poem-420c04cd6d2fe16dacb4d9f5","title":"古柏行","author":"杜甫","dynasty":"唐","verses":["孔明庙前有老柏，柯如青铜根如石。","霜皮溜雨四十围，黛色参天二千尺。","君臣已与时际会，树木犹为人爱惜。","云来气接巫峡长，月出寒通雪山白。","忆昨路绕锦亭东，先主武侯同閟宫。","崔嵬枝干郊原古，窈窕丹青户牖空。","落落盘踞虽得地，冥冥孤高多烈风。","扶持自是神明力，正直原因造化功。","大厦如倾要梁栋，万牛回首丘山重。","不露文章世已惊，未辞剪伐谁能送。","苦心岂免容蝼蚁，香叶终经宿鸾凤。","志士幽人莫怨嗟，古来材大难为用。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-383d41a8-5155-4fff-b91f-87d5585ff03e","tags":["隋・唐・五代","咏物","唐诗三百首","七言古诗","咏物诗","怀才不遇"]},{"id":"poem-420e42e375b245b4f6010f5b","title":"石犀行","author":"杜甫","dynasty":"唐","verses":["君不见秦时蜀太守，刻石立作三犀牛。","自古虽有厌胜法，天生江水向东流。","蜀人矜夸一千载，泛溢不近张仪楼。","今年灌口损户口，此事或恐为神羞。","终藉隄防出众力，高拥木石当清秋。","先王作法皆正道，鬼怪何得参人谋。","嗟尔三犀不经济，缺讹只与长川逝。","但见元气常调和，自免洪涛恣凋瘵。","安得壮士提天纲，再平水土犀奔茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9c1286ea-af42-4c24-8aa6-ebe54624d63e","tags":[]},{"id":"poem-422fb1ac3fb6ef0993145ae7","title":"菩萨蛮·绿云鬓上飞金雀","author":"牛峤","dynasty":"五代","verses":["绿云鬓上飞金雀，愁眉敛翠春烟薄。","香阁掩芙蓉，画屏山几重。","窗寒天欲曙，犹结同心苣。","啼粉污罗衣，问郎何日归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-19","tags":[]},{"id":"poem-4241d0dd99c315674abde343","title":"甘州子·曾如刘阮访仙踪","author":"顾敻","dynasty":"五代","verses":["曾如刘阮访仙踪，深洞客，此时逢。","绮筵散后绣衾同，款曲见韶容。","山枕上，长是怯晨钟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-43","tags":[]},{"id":"poem-42435ad1d73b88dc4c929928","title":"春秋战国门 子产","author":"周昙","dynasty":"唐","verses":["为政何门是化源，宽仁高下保安全。","如嫌水德人多狎，拯溺宜将猛济宽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2a504538-462d-42a4-a1fd-8465841458fe","tags":[]},{"id":"poem-42479bc404cc317c440aea99","title":"行思","author":"杨凝","dynasty":"唐","verses":["千里岂云去，欲归如路穷。","人间无暇日，马上又秋风。","破月衔高岳，流星拂晓空。","此时皆在梦，行色独怱怱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-475caaa3-edca-4365-b4d8-f7dfba41ea1c","tags":[]},{"id":"poem-424a39996e64b75a447001a4","title":"玉楼春·年年跃马长安市","author":"刘克庄","dynasty":"宋","verses":["年年跃马长安市。","客舍似家家似寄。","青钱换酒日无何，红烛呼庐宵不寐。","易挑锦妇机中字。","难得玉人心下事。","男儿西北有神州，莫滴水西桥畔泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-56","tags":["宋词三百首"]},{"id":"poem-424d582ff0ecdfcd342054e7","title":"斗鹌鹑","author":"杨景贤","dynasty":"元","verses":["恁娘那里望眼将穿，俺儿大灵魂儿尚有。","儿呵，则愿得性命完全，精神抖擞。","恰便似红叶儿飘香出御沟，淹淹地伴野鸥。","俺孩儿身向低行，谁肯道恩从亡流？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7951","tags":[]},{"id":"poem-42564529b56fb07e45c4d40f","title":"郊庙歌辞 享章怀太子庙乐章 迎神","author":"不详","dynasty":"唐","verses":["副君昭象，道应黄离。","铜楼备德，玉裕成规。","仙气霭霭，灵从师师。","前驱戾止，控鹤来仪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f03e0bf6-9cfd-4209-9617-f25c4499343a","tags":[]},{"id":"poem-4257c05bb71cb8ad7ec67345","title":"放鹦鹉二首  其二","author":"司马光","dynasty":"宋","verses":["虽道长安乐，争如在陇头。","林间祝圣主，万歳复千秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5d502386-0ccf-4d7b-804f-ba2ff0717804","tags":[]},{"id":"poem-425fd9b47b57e87d9ea81566","title":"彩塔赞","author":"李纲","dynasty":"宋","verses":["释迦佛说妙莲华，从地涌出七宝塔。","栏楯幡幢及龛室，宝玲璎珞震妙音。","四面皆出旃檀香，散天妙华以供养。","佛以右指开塔户，出大音声却关钥。","多宝如来示全身，赞叹说法分半座。","惟二如来共一塔，至今此会尚俨然。","何人建立窣堵波，种种严饰悉具足。","彩缕萦结尺寸间，高广五百由旬等。","当知一念周圆时，胜妙功德已成就。","若能瞻礼复回观，人人具此如来体。","至心持诵法华经，弹指真塔当出现。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-92861934-dfc5-40c9-a4f7-d44360091ae7","tags":[]},{"id":"poem-426793b6bb081c61c844420d","title":"董逃歌词","author":"曹操","dynasty":"汉","verses":["德行不亏缺，变故自难常。","郑康成行酒，伏地气绝；郭景图命尽于园桑。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-25","tags":[]},{"id":"poem-4267f84f5e24f5dd14ae9b97","title":"题石瓮寺","author":"马戴","dynasty":"唐","verses":["僧室并皇宫，云门辇路同。","渭分双阙北，山迥五陵东。","修绠悬林表，深泉汲洞中。","人烟窥垤蚁，鸳瓦拂冥鸿。","藓壁松生峭，龛灯月照空。","稀逢息心侣，独礼竺乾公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d181bfc0-594e-4fbd-b409-a37f59b16ed9","tags":[]},{"id":"poem-427256328cd456d69f158856","title":"江神子・江城子·十年生死两茫茫","author":"苏轼","dynasty":"宋","verses":["十年生死两茫茫。","不思量。","自难忘。","千里孤坟，无处话凄凉。","纵使相逢应不识，尘满面，鬓如霜。","夜来幽梦忽还乡。","小轩窗。","正梳妆。","相顾无言，惟有泪千行。","料得年年断肠处，明月夜，短松冈。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-44","tags":["宋词三百首"]},{"id":"poem-4273afc356dbc6b5239e790b","title":"乐游原","author":"李商隐","dynasty":"唐","verses":["向晚意不适，驱车登古原。","夕阳无限好，只是近黄昏。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d7c6d072-6e84-482e-856a-5a4c21226a3c","tags":["唐诗三百首","惜时","哲理"]},{"id":"poem-4286367bfa0b99fdf9588f3d","title":"效古","author":"皎然","dynasty":"唐","verses":["日出天地正，煌煌辟晨曦。","六龙驱群动，古今无尽时。","夸父亦何愚，竞走先自疲。","饮干咸池水，折尽扶桑枝。","渴死化爝火，嗟嗟徒尔为。","空留邓林在，折尽令人嗤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cf14fe00-0553-4519-9482-37eceabce9d1","tags":[]},{"id":"poem-429c7e99a5b5d12b8a82f192","title":"啸云","author":"释居简","dynasty":"宋","verses":["胡笳未奏边云悄，长啸一声山月小。","狂虏归思悲夜老，身未到家心已到。","山云不似塞云腥，云中倚阑时一声。","悠然清闻四十里，何独重围空万骑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d4451da6-d08c-4d0c-9117-306300d11395","tags":[]},{"id":"poem-429ef5c3f1b484c7c33ba5cf","title":"和君贶任少师园赏梅","author":"司马光","dynasty":"宋","verses":["寒压春头草未芽，喜闻置酒赏新葩。","官仪赫奕三川守，野意萧疏四皓家。","不用管弦妨淡泊，岂容桃李竞繁华。","昏鸦散乱传呼出，归路林间烛影斜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-06adc8c2-adf9-4631-82f4-0e8f33d0bda2","tags":[]},{"id":"poem-42b2394f658fd3d2a668aac6","title":"夜光篇","author":"王泠然","dynasty":"唐","verses":["游人夜到汝阳间，夜色冥蒙不解颜。","谁家暗起寒山烧，因此明中得见山。","山头山下须臾满，历险缘深无暂断。","焦声散著群树鸣，炎气傍林一川暖。","是时西北多海风，吹上连天光更雄。","浊烟熏月黑，高艳𦶟云红。","初谓炼丹仙灶里，还疑铸劒神谿中。","划为飞电来照物，乍作流星并上空。","西山无草光已灭，东顶荧荧犹未绝。","沸汤空谷数道水，融盖阴崖几年雪。","两京贫病若为居，四壁皆成凿照余。","未得贵游同秉烛，唯将半影借披书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-55b45ff4-173f-42d3-82bb-7f9404191f94","tags":[]},{"id":"poem-42ba29a6f65b3ef28a032282","title":"次章房陵韵四首  其二","author":"陈造","dynasty":"宋","verses":["诗法究源委，今古有正传。","寥寥风骚后，谁定执此权。","杜韩到黄陈，刃藏牛无全。","愧我蟁负山，良夜卓两肩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-952aaca6-d384-4163-8934-12b6101f6532","tags":[]},{"id":"poem-42c2e92f07aa639b7b7fd28c","title":"浪淘沙·乐事信难逢","author":"李弥逊","dynasty":"宋","verses":["乐事信难逢。","莫放匆匆。","飞红撩乱减春容。","临水不禁频送客，风袖龙锺。","小阁画堂东。","绮绣相重。","尊前谁唱夏云峰。","醒后欲寻溪上路，烟水无穷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-31","tags":[]},{"id":"poem-42cb062d127b762d013357e5","title":"柳十首 四","author":"李山甫","dynasty":"唐","verses":["只为遮楼又拂桥，被人摧折好枝条。","假饶张绪如今在，须把风流暗里销。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-dbcd044a-da3b-4c27-9b15-64bb44afe41d","tags":[]},{"id":"poem-42cef219c68873d558567cec","title":"送李少府贬峡中王少府贬长沙","author":"高适","dynasty":"唐","verses":["嗟君此别意何如，驻马衔桮问谪居。","巫峡啼猿数行泪，衡阳归雁几封书。","青枫江上秋天远，白帝城边古木疎。","圣代即今多雨露，暂时分手莫踌躇。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2c24cec1-4105-4511-bf8b-bc6d5d8d48c7","tags":["唐诗三百首","同情","送别","贬谪","边塞","七言律诗"]},{"id":"poem-42e34623d5561c16276cd9f1","title":"送友人游蜀","author":"张乔","dynasty":"唐","verses":["此心知者稀，欲别倍相依。","无食拟同去，有家还未归。","巴山开国远，劒道入天微。","必恐临邛客，疑君学赋非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-02f67006-a3bd-43ab-ad7a-6463c1100442","tags":[]}];
